// Hermes Agent Web UI — Auto-verified with node --check
export function renderHermesUI() {
  return "<!DOCTYPE html>\n<html lang=\"en\" class=\"dark\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\" />\n  <title>Hermes Agent \u2624 \u2014 Autonomous Workspace (Vertex AI + /data)</title>\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <script src=\"https://cdn.jsdelivr.net/npm/marked/marked.min.js\"></script>\n  <style>\n    :root { color-scheme: dark; }\n    body { background: #060911; color: #e2e8f0; font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, sans-serif; }\n    ::-webkit-scrollbar { width: 6px; height: 6px; }\n    ::-webkit-scrollbar-track { background: #090d16; }\n    ::-webkit-scrollbar-thumb { background: #263248; border-radius: 3px; }\n    .prose pre { background: #0b101d !important; border: 1px solid #1e293b; border-radius: 0.6rem; padding: 0.85rem; overflow-x: auto; font-size: 0.8rem; margin: 0.6rem 0; }\n    .prose code { color: #38bdf8; background: rgba(56,189,248,0.12); padding: 0.12rem 0.35rem; border-radius: 0.25rem; font-size: 0.84em; }\n    .prose pre code { background: transparent; padding: 0; color: #e2e8f0; }\n    .prose p { margin-bottom: 0.55rem; line-height: 1.6; }\n    .prose ul, .prose ol { margin-left: 1.25rem; margin-bottom: 0.55rem; list-style: disc; }\n    .thinking-box { background: rgba(139, 92, 246, 0.09); border-left: 3px solid #8b5cf6; }\n    .tool-box { background: rgba(16, 185, 129, 0.08); border-left: 3px solid #10b981; }\n    .nav-btn.active { background: rgba(99, 102, 241, 0.22); color: #a5b4fc; border-color: rgba(99, 102, 241, 0.55); font-weight: 600; }\n  </style>\n</head>\n<body class=\"h-[100dvh] flex flex-col overflow-hidden\">\n\n  <!-- LOGIN OVERLAY -->\n  <div id=\"loginOverlay\" class=\"fixed inset-0 z-50 bg-[#050811]/95 backdrop-blur-md flex items-center justify-center p-4 hidden\">\n    <div class=\"w-full max-w-md bg-[#0d1424] border border-slate-800 rounded-2xl shadow-2xl p-6 space-y-5\">\n      <div class=\"flex items-center gap-3\">\n        <div class=\"w-11 h-11 rounded-xl bg-gradient-to-br from-indigo-500 via-purple-600 to-amber-500 flex items-center justify-center font-bold text-xl text-white shadow-lg\">\u2624</div>\n        <div>\n          <h1 class=\"font-bold text-lg text-white\">Hermes Agent \u2624 Locked</h1>\n          <p class=\"text-xs text-slate-400\">Private Autonomous Workspace \u2022 Vertex AI + /data</p>\n        </div>\n      </div>\n      <form onsubmit=\"submitLogin(event)\" class=\"space-y-4\">\n        <div>\n          <label class=\"block text-xs font-medium text-slate-300 mb-1\">Username / Email</label>\n          <input id=\"loginUsername\" type=\"email\" required value=\"admin@example.com\" placeholder=\"admin@example.com\"\n            class=\"w-full bg-slate-900 border border-slate-700 rounded-xl px-3.5 py-2.5 text-sm text-white focus:outline-none focus:border-indigo-500\" />\n        </div>\n        <div>\n          <label class=\"block text-xs font-medium text-slate-300 mb-1\">Password</label>\n          <input id=\"loginPassword\" type=\"password\" required placeholder=\"Enter owner password\"\n            class=\"w-full bg-slate-900 border border-slate-700 rounded-xl px-3.5 py-2.5 text-sm text-white focus:outline-none focus:border-indigo-500\" />\n        </div>\n        <div id=\"loginError\" class=\"text-xs text-red-400 hidden\"></div>\n        <button id=\"loginBtn\" type=\"submit\"\n          class=\"w-full py-2.5 px-4 bg-indigo-600 hover:bg-indigo-500 text-white font-semibold rounded-xl text-sm transition shadow-lg\">\n          Unlock Hermes Workspace\n        </button>\n      </form>\n    </div>\n  </div>\n\n  <!-- TOP HEADER & NAVIGATION -->\n  <header class=\"border-b border-slate-800/90 bg-[#0a0f1c] px-2.5 py-2 shrink-0 z-30 space-y-2\">\n    <!-- Row 1: Brand + Status Badges + Model/Thinking/Toolset Selectors -->\n    <div class=\"flex flex-wrap items-center justify-between gap-2\">\n      <div class=\"flex items-center gap-2\">\n        <button type=\"button\" onclick=\"toggleMobileSidebar()\" class=\"md:hidden px-2.5 py-1.5 rounded-lg bg-slate-800 text-slate-200 border border-slate-700 text-xs font-bold\" title=\"Toggle Sessions Drawer\">\u2630</button>\n        <div class=\"w-7 h-7 rounded-lg bg-gradient-to-br from-amber-500 via-indigo-500 to-purple-600 flex items-center justify-center font-bold text-sm text-white shadow\">\u2624</div>\n        <span class=\"font-bold text-sm text-white tracking-tight\">Hermes Agent</span>\n        <span id=\"vmBridgeBadge\" class=\"text-[10px] px-1.5 py-0.5 rounded bg-emerald-500/15 text-emerald-300 border border-emerald-500/30 font-mono\">\u25cf /data Online</span>\n        <button type=\"button\" onclick=\"switchTab('jobs')\" id=\"bgJobsBadge\" class=\"text-[10px] px-2 py-0.5 rounded bg-indigo-500/15 text-indigo-300 border border-indigo-500/30 font-mono hover:bg-indigo-500/25\">\u26a1 BG: Ready</button>\n      </div>\n\n      <!-- Model + Thinking + Toolset + Background Mode Controls -->\n      <div class=\"flex flex-wrap items-center gap-1.5 w-full md:w-auto justify-end\">\n        <select id=\"modelSelect\" onchange=\"onModelChange()\" title=\"Select Google Vertex AI Gemini Model\"\n          class=\"flex-1 md:flex-initial bg-slate-900 border border-indigo-500/50 text-xs text-white font-medium rounded-lg px-2.5 py-1.5 focus:outline-none focus:border-indigo-400 min-w-[170px] max-w-full md:max-w-[250px]\">\n          <option value=\"gemini-3.8-flash\">Loading 21 Gemini Models...</option>\n        </select>\n\n        <select id=\"thinkingSelect\" onchange=\"onThinkingChange()\" title=\"Thinking Budget Level\"\n          class=\"bg-slate-900 border border-purple-500/40 text-xs text-purple-200 rounded-lg px-2 py-1.5 focus:outline-none\">\n          <option value=\"auto\">\ud83e\udde0 Think: Auto</option>\n          <option value=\"off\">\u26a1 Think: Off</option>\n          <option value=\"low\">\ud83e\udde0 Low (1K)</option>\n          <option value=\"medium\">\ud83e\udde0 Med (4K)</option>\n          <option value=\"high\">\ud83e\udde0 High (16K)</option>\n          <option value=\"max\">\ud83e\udde0 Max (24K)</option>\n        </select>\n\n        <select id=\"toolsetSelect\" onchange=\"onToolsetChange()\" title=\"Active Hermes Toolset Posture\"\n          class=\"bg-slate-900 border border-emerald-500/40 text-xs text-emerald-200 rounded-lg px-2 py-1.5 focus:outline-none\">\n          <option value=\"hermes-cli\">\ud83d\udee0\ufe0f Tools: All 19</option>\n          <option value=\"coding\">\ud83d\udee0\ufe0f Coding</option>\n          <option value=\"web\">\ud83d\udee0\ufe0f Web</option>\n          <option value=\"debugging\">\ud83d\udee0\ufe0f Debug</option>\n          <option value=\"safe\">\ud83d\udee0\ufe0f Safe</option>\n          <option value=\"off\">\ud83d\udee0\ufe0f Off</option>\n        </select>\n\n        <button type=\"button\" id=\"bgModeBtn\" onclick=\"toggleBgMode()\" title=\"When ON, tasks continue executing in the background even if you close your phone browser or lock your screen\"\n          class=\"text-[11px] px-2.5 py-1.5 rounded-lg bg-emerald-600/25 border border-emerald-500/50 text-emerald-200 font-semibold whitespace-nowrap\">\n          \ud83d\udd04 Keep-Alive: ON\n        </button>\n\n        <button type=\"button\" onclick=\"logout()\" title=\"Lock Workspace\"\n          class=\"text-xs px-2.5 py-1.5 rounded-lg bg-slate-800 hover:bg-red-950/70 text-slate-300 hover:text-red-300 border border-slate-700\">\ud83d\udd12</button>\n      </div>\n    </div>\n\n    <!-- Row 2: 8 Navigation Tabs (Scrollable on Mobile) -->\n    <nav class=\"flex items-center gap-1 overflow-x-auto pb-0.5 no-scrollbar\">\n      <button type=\"button\" onclick=\"switchTab('chat')\" id=\"tabBtn-chat\" class=\"nav-btn active text-xs px-2.5 py-1 rounded-lg border border-transparent hover:bg-slate-800/80 transition whitespace-nowrap\">\ud83d\udcac Chat</button>\n      <button type=\"button\" onclick=\"switchTab('jobs')\" id=\"tabBtn-jobs\" class=\"nav-btn text-xs px-2.5 py-1 rounded-lg border border-transparent hover:bg-slate-800/80 transition whitespace-nowrap\">\u26a1 Background Jobs <span id=\"navJobCount\" class=\"text-[10px] bg-indigo-900/70 text-indigo-200 px-1.5 rounded\">0</span></button>\n      <button type=\"button\" onclick=\"switchTab('terminal')\" id=\"tabBtn-terminal\" class=\"nav-btn text-xs px-2.5 py-1 rounded-lg border border-transparent hover:bg-slate-800/80 transition whitespace-nowrap\">\ud83d\udcbb Terminal & Code</button>\n      <button type=\"button\" onclick=\"switchTab('skills')\" id=\"tabBtn-skills\" class=\"nav-btn text-xs px-2.5 py-1 rounded-lg border border-transparent hover:bg-slate-800/80 transition whitespace-nowrap\">\ud83d\udcda Skills <span id=\"navSkillCount\" class=\"text-[10px] bg-slate-800 px-1 rounded\">60</span></button>\n      <button type=\"button\" onclick=\"switchTab('memory')\" id=\"tabBtn-memory\" class=\"nav-btn text-xs px-2.5 py-1 rounded-lg border border-transparent hover:bg-slate-800/80 transition whitespace-nowrap\">\ud83e\udde0 Memory & SOUL</button>\n      <button type=\"button\" onclick=\"switchTab('kanban')\" id=\"tabBtn-kanban\" class=\"nav-btn text-xs px-2.5 py-1 rounded-lg border border-transparent hover:bg-slate-800/80 transition whitespace-nowrap\">\ud83d\udccb Kanban & Todos</button>\n      <button type=\"button\" onclick=\"switchTab('cron')\" id=\"tabBtn-cron\" class=\"nav-btn text-xs px-2.5 py-1 rounded-lg border border-transparent hover:bg-slate-800/80 transition whitespace-nowrap\">\u23f0 Cron</button>\n      <button type=\"button\" onclick=\"switchTab('files')\" id=\"tabBtn-files\" class=\"nav-btn text-xs px-2.5 py-1 rounded-lg border border-transparent hover:bg-slate-800/80 transition whitespace-nowrap\">\ud83d\udcc1 /data Files</button>\n      <button type=\"button\" onclick=\"switchTab('system')\" id=\"tabBtn-system\" class=\"nav-btn text-xs px-2.5 py-1 rounded-lg border border-transparent hover:bg-slate-800/80 transition whitespace-nowrap\">\ud83e\ude7a Doctor & Stats</button>\n    </nav>\n  </header>\n\n  <!-- MAIN WORKSPACE BODY -->\n  <div class=\"flex-1 flex overflow-hidden relative\">\n\n    <!-- ==================== TAB 1: CHAT & AGENT STUDIO ==================== -->\n    <div id=\"tab-chat\" class=\"flex-1 flex overflow-hidden relative\">\n      <!-- Sessions Sidebar (Responsive Drawer on Mobile, Fixed on Desktop) -->\n      <aside id=\"sessionSidebar\" class=\"hidden md:flex w-64 bg-[#0a0f1c] border-r border-slate-800/80 flex-col shrink-0 z-30 absolute md:static inset-y-0 left-0 shadow-2xl md:shadow-none\">\n        <div class=\"p-2.5 border-b border-slate-800/80 space-y-2\">\n          <div class=\"flex items-center gap-1.5\">\n            <button type=\"button\" onclick=\"createNewSession()\" class=\"flex-1 py-2 px-3 bg-indigo-600 hover:bg-indigo-500 text-white font-semibold rounded-lg text-xs flex items-center justify-center gap-1 shadow transition\">\n              <span>\uff0b New Session</span>\n            </button>\n            <button type=\"button\" onclick=\"toggleMobileSidebar()\" class=\"md:hidden px-2.5 py-2 rounded-lg bg-slate-800 text-slate-300 text-xs\">\u2715</button>\n          </div>\n          <input id=\"sessionSearchInput\" oninput=\"filterSessions()\" type=\"text\" placeholder=\"\ud83d\udd0d Search sessions...\"\n            class=\"w-full bg-slate-900 border border-slate-800 rounded-lg px-2.5 py-1.5 text-xs text-slate-200 focus:outline-none focus:border-indigo-500\" />\n        </div>\n        <div id=\"sessionList\" class=\"flex-1 overflow-y-auto p-2 space-y-1\"></div>\n        <!-- Quick Slash Command Bar -->\n        <div class=\"p-2.5 border-t border-slate-800/80 bg-slate-950/60 space-y-1.5\">\n          <div class=\"text-[10px] font-semibold uppercase tracking-wider text-slate-400\">Quick Slash Commands</div>\n          <div class=\"flex flex-wrap gap-1\">\n            <button type=\"button\" onclick=\"runQuickSlash('/help')\" class=\"text-[10px] px-1.5 py-0.5 rounded bg-slate-800 hover:bg-slate-700 text-slate-200 font-mono\">/help</button>\n            <button type=\"button\" onclick=\"runQuickSlash('/doctor')\" class=\"text-[10px] px-1.5 py-0.5 rounded bg-slate-800 hover:bg-slate-700 text-emerald-300 font-mono\">/doctor</button>\n            <button type=\"button\" onclick=\"runQuickSlash('/usage')\" class=\"text-[10px] px-1.5 py-0.5 rounded bg-slate-800 hover:bg-slate-700 text-sky-300 font-mono\">/usage</button>\n            <button type=\"button\" onclick=\"runQuickSlash('/compress')\" class=\"text-[10px] px-1.5 py-0.5 rounded bg-slate-800 hover:bg-slate-700 text-purple-300 font-mono\">/compress</button>\n            <button type=\"button\" onclick=\"runQuickSlash('/retry')\" class=\"text-[10px] px-1.5 py-0.5 rounded bg-slate-800 hover:bg-slate-700 text-amber-300 font-mono\">/retry</button>\n            <button type=\"button\" onclick=\"runQuickSlash('/undo')\" class=\"text-[10px] px-1.5 py-0.5 rounded bg-slate-800 hover:bg-slate-700 text-rose-300 font-mono\">/undo</button>\n          </div>\n        </div>\n      </aside>\n\n      <!-- Main Chat Column -->\n      <main class=\"flex-1 flex flex-col bg-[#060911] overflow-hidden relative\">\n        <!-- Standing Goal Banner -->\n        <div id=\"goalBanner\" class=\"hidden bg-amber-500/10 border-b border-amber-500/30 px-4 py-1.5 flex items-center justify-between text-xs text-amber-200\">\n          <div>\ud83c\udfaf <b>Active Goal:</b> <span id=\"goalText\"></span></div>\n          <button type=\"button\" onclick=\"setGoal('')\" class=\"text-[10px] underline hover:text-white\">Clear</button>\n        </div>\n\n        <!-- Preloaded Skill Banner -->\n        <div id=\"activeSkillBanner\" class=\"hidden bg-indigo-500/10 border-b border-indigo-500/30 px-4 py-1.5 flex items-center justify-between text-xs text-indigo-200\">\n          <div>\ud83d\udcda <b>Active Skill:</b> <span id=\"activeSkillName\" class=\"font-mono\"></span></div>\n          <button type=\"button\" onclick=\"clearPreloadedSkill()\" class=\"text-[10px] underline hover:text-white\">Detach</button>\n        </div>\n\n        <!-- Live Background Running Banner -->\n        <div id=\"liveBgBanner\" class=\"hidden bg-emerald-500/10 border-b border-emerald-500/30 px-4 py-1.5 flex items-center justify-between text-xs text-emerald-200 animate-pulse\">\n          <div>\u26a1 <b>Background Execution Active:</b> Hermes is running on Cloudflare + Spot VM (`/data/hermes`). Safe to close browser or lock phone!</div>\n          <button type=\"button\" onclick=\"pollActiveSession(true)\" class=\"text-[10px] px-2 py-0.5 rounded bg-emerald-600/30 border border-emerald-500/40\">\u21bb Sync Now</button>\n        </div>\n\n        <!-- Messages Stream -->\n        <div id=\"chatMessages\" class=\"flex-1 overflow-y-auto p-3 md:p-6 space-y-4\"></div>\n\n        <!-- Slash Command Autocomplete Popup -->\n        <div id=\"slashPopup\" class=\"hidden absolute bottom-20 left-3 right-3 md:left-6 md:right-6 max-w-2xl bg-[#0e1526] border border-indigo-500/50 rounded-2xl shadow-2xl p-2 z-40 max-h-64 overflow-y-auto\"></div>\n\n        <!-- Image Attachment Preview -->\n        <div id=\"imagePreviewBar\" class=\"hidden px-4 py-2 bg-slate-900/95 border-t border-slate-800 flex items-center justify-between\">\n          <div class=\"flex items-center gap-2 text-xs text-sky-300\">\n            <span>\ud83d\uddbc\ufe0f Image attached for Gemini Vision:</span>\n            <span id=\"imagePreviewName\" class=\"font-mono text-slate-300\"></span>\n          </div>\n          <button type=\"button\" onclick=\"clearImageAttachment()\" class=\"text-xs text-red-400 hover:underline\">Remove</button>\n        </div>\n\n        <!-- Chat Composer -->\n        <div class=\"p-2.5 md:p-3.5 border-t border-slate-800/90 bg-[#0a0f1c]\">\n          <form onsubmit=\"sendMessage(event)\" class=\"max-w-5xl mx-auto flex gap-1.5 md:gap-2 items-end\">\n            <input type=\"file\" id=\"imageInput\" accept=\"image/*\" class=\"hidden\" onchange=\"handleImageUpload(event)\" />\n            <button type=\"button\" id=\"slashBtn\" onclick=\"toggleSlashMenu()\" title=\"Open Slash Commands (/help, /moa, /learn, /doctor, /model)\"\n              class=\"px-3 py-2.5 rounded-xl bg-indigo-600/25 hover:bg-indigo-600/40 text-indigo-200 border border-indigo-500/40 font-mono font-bold text-sm shrink-0\">/</button>\n            <button type=\"button\" onclick=\"document.getElementById('imageInput').click()\" title=\"Attach Image for Gemini Vision\"\n              class=\"p-2.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-300 border border-slate-700 shrink-0\">\ud83d\uddbc\ufe0f</button>\n            <button type=\"button\" onclick=\"toggleVoiceInput()\" id=\"micBtn\" title=\"Voice Input (Speech-to-Text)\"\n              class=\"p-2.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-300 border border-slate-700 shrink-0 hidden sm:inline-flex\">\ud83c\udf99\ufe0f</button>\n            <textarea id=\"chatInput\" rows=\"2\" oninput=\"onChatInput()\" placeholder=\"Ask Hermes anything, or tap [/] for commands (/moa, /learn, /doctor, /goal)... Works in background if you close tab!\"\n              class=\"flex-1 bg-slate-900 border border-slate-700/90 rounded-xl px-3 py-2 text-sm text-white placeholder-slate-500 focus:outline-none focus:border-indigo-500 resize-none\"\n              onkeydown=\"if(event.key==='Enter' && !event.shiftKey){event.preventDefault(); sendMessage(event);}\"></textarea>\n            <button id=\"sendBtn\" type=\"submit\"\n              class=\"px-4 md:px-5 py-2.5 bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 text-white font-semibold rounded-xl text-sm transition shadow-lg shrink-0\">\n              Send \u21b5\n            </button>\n          </form>\n        </div>\n      </main>\n    </div>\n\n    <!-- ==================== TAB 2: BACKGROUND JOBS MONITOR ==================== -->\n    <div id=\"tab-jobs\" class=\"hidden flex-1 flex flex-col overflow-hidden bg-[#060911] p-4 md:p-6 space-y-4\">\n      <div class=\"flex flex-wrap items-center justify-between gap-2 bg-[#0a0f1c] border border-slate-800 rounded-xl p-4\">\n        <div>\n          <h2 class=\"text-sm font-bold text-white\">\u26a1 Unstoppable Background Execution Queue (Phone & Tab-Close Resilient)</h2>\n          <p class=\"text-xs text-slate-400\">Tasks submitted with Keep-Alive ON run on Cloudflare Edge + Spot VM (`/data/hermes`) via `ctx.waitUntil()`. Even if you close your phone browser or lock your screen, they finish and save to `/data/hermes/storage/hermes_store.db`.</p>\n        </div>\n        <button type=\"button\" onclick=\"loadJobsTab()\" class=\"px-3 py-1.5 bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-semibold rounded-lg\">\u21bb Refresh Jobs</button>\n      </div>\n      <div id=\"jobsListContainer\" class=\"flex-1 overflow-y-auto space-y-2.5\"></div>\n    </div>\n\n    <!-- ==================== TAB 3: LIVE TERMINAL & CODE RUNNER ==================== -->\n    <div id=\"tab-terminal\" class=\"hidden flex-1 flex flex-col md:flex-row overflow-hidden bg-[#060911]\">\n      <div class=\"flex-1 flex flex-col border-b md:border-b-0 md:border-r border-slate-800 overflow-hidden\">\n        <div class=\"p-3 bg-[#0a0f1c] border-b border-slate-800 flex flex-wrap items-center justify-between gap-2\">\n          <div class=\"flex items-center gap-2\">\n            <span class=\"text-xs font-bold text-emerald-400 font-mono\">root@az-spot-vm:/data/hermes$</span>\n            <span class=\"text-[11px] text-slate-400\">Live Spot VM Bash Terminal</span>\n          </div>\n          <div class=\"flex flex-wrap gap-1.5\">\n            <button type=\"button\" onclick=\"runQuickTerm('df -h /data && systemctl is-active hermes-dashboard.service hermes-sync.service hermes-bridge.service')\" class=\"text-[11px] px-2 py-1 rounded bg-slate-800 hover:bg-slate-700 text-slate-200\">Check /data & Services</button>\n            <button type=\"button\" onclick=\"runQuickTerm('hermes --version && hermes status')\" class=\"text-[11px] px-2 py-1 rounded bg-slate-800 hover:bg-slate-700 text-indigo-300\">hermes status</button>\n            <button type=\"button\" onclick=\"document.getElementById('termOutput').textContent=''\" class=\"text-[11px] px-2 py-1 rounded bg-slate-800 hover:bg-slate-700 text-slate-400\">Clear</button>\n          </div>\n        </div>\n        <div id=\"termOutput\" class=\"flex-1 bg-[#04070e] p-4 font-mono text-xs text-emerald-300 overflow-y-auto whitespace-pre-wrap\">Ready. Type any bash command below to execute live on /data/hermes.</div>\n        <form onsubmit=\"execTerminalForm(event)\" class=\"p-2.5 bg-[#0a0f1c] border-t border-slate-800 flex gap-2\">\n          <input id=\"termWorkdir\" type=\"text\" value=\"/data/hermes\" class=\"w-28 md:w-36 bg-slate-900 border border-slate-700 rounded-lg px-2 py-1.5 text-xs font-mono text-slate-300\" />\n          <input id=\"termCmdInput\" type=\"text\" placeholder=\"Enter bash command (e.g. ls -la /data/hermes)...\"\n            class=\"flex-1 bg-slate-900 border border-slate-700 rounded-lg px-3 py-1.5 text-xs font-mono text-white focus:outline-none focus:border-emerald-500\" />\n          <button type=\"submit\" class=\"px-4 py-1.5 bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-semibold rounded-lg\">Run</button>\n        </form>\n      </div>\n\n      <!-- Multi-Language Code Sandbox -->\n      <div class=\"w-full md:w-[46%] flex flex-col overflow-hidden\">\n        <div class=\"p-3 bg-[#0a0f1c] border-b border-slate-800 flex items-center justify-between\">\n          <span class=\"text-xs font-bold text-sky-400\">\u26a1 Hermes Code Sandbox (execute_code)</span>\n          <div class=\"flex items-center gap-2\">\n            <select id=\"codeLangSelect\" class=\"bg-slate-900 border border-slate-700 rounded px-2 py-1 text-xs text-white\">\n              <option value=\"python\">Python 3</option>\n              <option value=\"javascript\">Node.js</option>\n              <option value=\"bash\">Bash Script</option>\n            </select>\n            <button type=\"button\" onclick=\"runSandboxCode()\" class=\"px-3 py-1 bg-sky-600 hover:bg-sky-500 text-white text-xs font-semibold rounded\">\u25b6 Execute</button>\n          </div>\n        </div>\n        <textarea id=\"codeEditorInput\" class=\"flex-1 bg-[#080c17] p-3 font-mono text-xs text-slate-100 focus:outline-none border-b border-slate-800 resize-none\">import os, platform, sqlite3\nprint(\"Host:\", platform.node())\nprint(\"Persistent /data contents:\", os.listdir(\"/data/hermes\"))\nconn = sqlite3.connect(\"/data/hermes/storage/hermes_store.db\")\nprint(\"Synced sessions on /data:\", conn.execute(\"SELECT count(*) FROM sessions\").fetchone()[0])</textarea>\n        <div id=\"codeRunnerOutput\" class=\"h-44 bg-[#04070e] p-3 font-mono text-xs text-sky-200 overflow-y-auto whitespace-pre-wrap\">Click \"\u25b6 Execute\" to run on Spot VM.</div>\n      </div>\n    </div>\n\n    <!-- ==================== TAB 4: SKILLS HUB (60+ SKILLS) ==================== -->\n    <div id=\"tab-skills\" class=\"hidden flex-1 flex flex-col md:flex-row overflow-hidden bg-[#060911]\">\n      <div class=\"w-full md:w-80 border-b md:border-b-0 md:border-r border-slate-800 bg-[#0a0f1c] flex flex-col max-h-64 md:max-h-none\">\n        <div class=\"p-3 border-b border-slate-800 space-y-2\">\n          <div class=\"flex items-center justify-between\">\n            <h2 class=\"text-xs font-bold uppercase tracking-wider text-slate-300\">Hermes Skills Hub</h2>\n            <button type=\"button\" onclick=\"openNewSkillEditor()\" class=\"text-xs px-2 py-1 bg-indigo-600 hover:bg-indigo-500 text-white rounded\">+ New Skill</button>\n          </div>\n          <input id=\"skillSearchInput\" oninput=\"renderSkillsList()\" type=\"text\" placeholder=\"Search 60+ skills...\"\n            class=\"w-full bg-slate-900 border border-slate-700 rounded-lg px-2.5 py-1.5 text-xs text-white\" />\n          <select id=\"skillCategoryFilter\" onchange=\"renderSkillsList()\" class=\"w-full bg-slate-900 border border-slate-700 rounded-lg px-2 py-1.5 text-xs text-slate-200\">\n            <option value=\"\">All Categories</option>\n          </select>\n        </div>\n        <div id=\"skillsListContainer\" class=\"flex-1 overflow-y-auto p-2 space-y-1.5\"></div>\n      </div>\n      <div class=\"flex-1 flex flex-col overflow-hidden\">\n        <div class=\"p-3 bg-[#0a0f1c] border-b border-slate-800 flex flex-wrap items-center justify-between gap-2\">\n          <div>\n            <span id=\"skillViewerTitle\" class=\"text-sm font-bold text-white\">Select a skill to inspect or edit</span>\n            <span id=\"skillViewerMeta\" class=\"text-xs text-slate-400 ml-2 font-mono\"></span>\n          </div>\n          <div class=\"flex items-center gap-2\">\n            <button type=\"button\" onclick=\"activateSkillInChat()\" id=\"useSkillBtn\" class=\"hidden px-3 py-1.5 bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-semibold rounded-lg\">\u25b6 Use Skill in Chat</button>\n            <button type=\"button\" onclick=\"saveSkillFromEditor()\" id=\"saveSkillBtn\" class=\"hidden px-3 py-1.5 bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-semibold rounded-lg\">\ud83d\udcbe Save to /data & R2</button>\n          </div>\n        </div>\n        <textarea id=\"skillContentEditor\" class=\"flex-1 bg-[#060911] p-4 font-mono text-xs text-slate-200 focus:outline-none resize-none\" placeholder=\"Skill SKILL.md content will appear here...\"></textarea>\n      </div>\n    </div>\n\n    <!-- ==================== TAB 5: MEMORY & PERSONA ==================== -->\n    <div id=\"tab-memory\" class=\"hidden flex-1 flex flex-col md:flex-row overflow-hidden bg-[#060911]\">\n      <div class=\"flex-1 flex flex-col border-b md:border-b-0 md:border-r border-slate-800 overflow-hidden\">\n        <div class=\"p-3 bg-[#0a0f1c] border-b border-slate-800 flex flex-wrap items-center justify-between gap-2\">\n          <div class=\"flex items-center gap-2\">\n            <span class=\"text-xs font-bold text-purple-300\">\ud83e\uddec Persona & Core Memory (/data/hermes/.hermes/)</span>\n            <select id=\"personaPresetSelect\" onchange=\"applyPersonaPreset()\" class=\"bg-slate-900 border border-slate-700 rounded px-2 py-1 text-xs text-slate-200\">\n              <option value=\"\">Load Personality Preset...</option>\n              <option value=\"default\">Hermes Default (Direct & Action-Oriented)</option>\n              <option value=\"architect\">Principal Cloud & Systems Architect</option>\n              <option value=\"researcher\">Deep Scientific Researcher</option>\n              <option value=\"coder\">Autonomous Full-Stack Engineer</option>\n              <option value=\"concise\">Ultra-Concise Executive</option>\n            </select>\n          </div>\n          <button type=\"button\" onclick=\"savePersonaFiles()\" class=\"px-3 py-1.5 bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-semibold rounded-lg\">\ud83d\udcbe Save All to /data & R2</button>\n        </div>\n        <div class=\"flex-1 grid grid-rows-3 divide-y divide-slate-800 overflow-y-auto\">\n          <div class=\"p-3 flex flex-col\">\n            <label class=\"text-xs font-bold text-amber-300 mb-1 font-mono\">SOUL.md \u2014 Agent Persona & Identity</label>\n            <textarea id=\"soulMdInput\" class=\"flex-1 bg-slate-900/80 border border-slate-800 rounded-lg p-2.5 text-xs font-mono text-slate-100 resize-none focus:outline-none\"></textarea>\n          </div>\n          <div class=\"p-3 flex flex-col\">\n            <label class=\"text-xs font-bold text-emerald-300 mb-1 font-mono\">MEMORY.md \u2014 Long-Term Curated Knowledge</label>\n            <textarea id=\"memoryMdInput\" class=\"flex-1 bg-slate-900/80 border border-slate-800 rounded-lg p-2.5 text-xs font-mono text-slate-100 resize-none focus:outline-none\"></textarea>\n          </div>\n          <div class=\"p-3 flex flex-col\">\n            <label class=\"text-xs font-bold text-sky-300 mb-1 font-mono\">USER.md \u2014 User Profile & Environment</label>\n            <textarea id=\"userMdInput\" class=\"flex-1 bg-slate-900/80 border border-slate-800 rounded-lg p-2.5 text-xs font-mono text-slate-100 resize-none focus:outline-none\"></textarea>\n          </div>\n        </div>\n      </div>\n      <div class=\"w-full md:w-96 flex flex-col bg-[#0a0f1c] overflow-hidden\">\n        <div class=\"p-3 border-b border-slate-800\">\n          <h3 class=\"text-xs font-bold uppercase tracking-wider text-slate-300 mb-2\">Structured Memory Facts</h3>\n          <form onsubmit=\"addMemoryFact(event)\" class=\"flex gap-1.5\">\n            <input id=\"newMemoryFactInput\" type=\"text\" placeholder=\"Add persistent memory fact...\"\n              class=\"flex-1 bg-slate-900 border border-slate-700 rounded-lg px-2.5 py-1.5 text-xs text-white\" />\n            <button type=\"submit\" class=\"px-3 py-1.5 bg-purple-600 hover:bg-purple-500 text-white text-xs font-semibold rounded-lg\">Add</button>\n          </form>\n        </div>\n        <div id=\"memoryFactsList\" class=\"flex-1 overflow-y-auto p-3 space-y-2\"></div>\n      </div>\n    </div>\n\n    <!-- ==================== TAB 6: KANBAN & TODOS ==================== -->\n    <div id=\"tab-kanban\" class=\"hidden flex-1 flex flex-col overflow-hidden bg-[#060911]\">\n      <div class=\"p-3 bg-[#0a0f1c] border-b border-slate-800 flex flex-wrap items-center justify-between gap-2\">\n        <div>\n          <h2 class=\"text-sm font-bold text-white\">\ud83d\udccb Multi-Agent Kanban Board & Todo Queue</h2>\n          <span class=\"text-xs text-slate-400\">Dispatch tasks to autonomous Gemini subagents (runs in background!)</span>\n        </div>\n        <form onsubmit=\"createKanbanCardUI(event)\" class=\"flex items-center gap-1.5\">\n          <input id=\"kbTitleInput\" type=\"text\" required placeholder=\"New Kanban task title...\" class=\"bg-slate-900 border border-slate-700 rounded-lg px-2.5 py-1.5 text-xs text-white w-48 md:w-60\" />\n          <select id=\"kbPriorityInput\" class=\"bg-slate-900 border border-slate-700 rounded-lg px-2 py-1.5 text-xs text-slate-200\">\n            <option value=\"medium\">Medium</option>\n            <option value=\"high\">High</option>\n            <option value=\"critical\">Critical</option>\n          </select>\n          <button type=\"submit\" class=\"px-3 py-1.5 bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-semibold rounded-lg\">+ Add Task</button>\n        </form>\n      </div>\n      <div class=\"flex-1 flex overflow-x-auto p-3 gap-3\">\n        <div class=\"w-64 shrink-0 bg-[#0a0f1c] border border-slate-800 rounded-xl flex flex-col\"><div class=\"p-2.5 border-b border-slate-800 text-xs font-bold text-slate-300\">\ud83d\udccc Backlog (todo)</div><div id=\"kb-col-todo\" class=\"flex-1 p-2 space-y-2 overflow-y-auto\"></div></div>\n        <div class=\"w-64 shrink-0 bg-[#0a0f1c] border border-slate-800 rounded-xl flex flex-col\"><div class=\"p-2.5 border-b border-slate-800 text-xs font-bold text-sky-400\">\u26a1 In Progress</div><div id=\"kb-col-in_progress\" class=\"flex-1 p-2 space-y-2 overflow-y-auto\"></div></div>\n        <div class=\"w-64 shrink-0 bg-[#0a0f1c] border border-slate-800 rounded-xl flex flex-col\"><div class=\"p-2.5 border-b border-slate-800 text-xs font-bold text-purple-400\">\ud83d\udd0d In Review</div><div id=\"kb-col-review\" class=\"flex-1 p-2 space-y-2 overflow-y-auto\"></div></div>\n        <div class=\"w-64 shrink-0 bg-[#0a0f1c] border border-slate-800 rounded-xl flex flex-col\"><div class=\"p-2.5 border-b border-slate-800 text-xs font-bold text-rose-400\">\u26d4 Blocked</div><div id=\"kb-col-blocked\" class=\"flex-1 p-2 space-y-2 overflow-y-auto\"></div></div>\n        <div class=\"w-64 shrink-0 bg-[#0a0f1c] border border-slate-800 rounded-xl flex flex-col\"><div class=\"p-2.5 border-b border-slate-800 text-xs font-bold text-emerald-400\">\u2705 Completed</div><div id=\"kb-col-done\" class=\"flex-1 p-2 space-y-2 overflow-y-auto\"></div></div>\n        <div class=\"w-72 shrink-0 bg-[#0a0f1c] border border-slate-800 rounded-xl flex flex-col\">\n          <div class=\"p-2.5 border-b border-slate-800 text-xs font-bold text-amber-300\">\ud83d\udcdd Session Todo List</div>\n          <form onsubmit=\"addTodoUI(event)\" class=\"p-2 border-b border-slate-800 flex gap-1\">\n            <input id=\"todoTitleInput\" type=\"text\" required placeholder=\"Add todo...\" class=\"flex-1 bg-slate-900 border border-slate-700 rounded px-2 py-1 text-xs text-white\" />\n            <button type=\"submit\" class=\"px-2.5 py-1 bg-amber-600 text-white text-xs rounded\">+</button>\n          </form>\n          <div id=\"todoListContainer\" class=\"flex-1 p-2 space-y-1.5 overflow-y-auto\"></div>\n        </div>\n      </div>\n    </div>\n\n    <!-- ==================== TAB 7: CRON AUTOMATIONS ==================== -->\n    <div id=\"tab-cron\" class=\"hidden flex-1 flex flex-col md:flex-row overflow-hidden bg-[#060911]\">\n      <div class=\"w-full md:w-96 border-b md:border-b-0 md:border-r border-slate-800 bg-[#0a0f1c] p-4 space-y-4 overflow-y-auto\">\n        <h2 class=\"text-sm font-bold text-white\">\u23f0 Create Scheduled Automation</h2>\n        <form onsubmit=\"createCronUI(event)\" class=\"space-y-3\">\n          <div>\n            <label class=\"text-xs text-slate-400 block mb-1\">Job Name</label>\n            <input id=\"cronNameInput\" type=\"text\" required placeholder=\"Daily /data Health & Backup Audit\" class=\"w-full bg-slate-900 border border-slate-700 rounded-lg px-3 py-1.5 text-xs text-white\" />\n          </div>\n          <div>\n            <label class=\"text-xs text-slate-400 block mb-1\">Schedule (Cron Expression)</label>\n            <input id=\"cronSchedInput\" type=\"text\" required value=\"0 */6 * * *\" class=\"w-full bg-slate-900 border border-slate-700 rounded-lg px-3 py-1.5 text-xs font-mono text-white\" />\n          </div>\n          <div>\n            <label class=\"text-xs text-slate-400 block mb-1\">Agent Task Prompt</label>\n            <textarea id=\"cronPromptInput\" rows=\"3\" required placeholder=\"Check /data disk usage, verify systemd services, and summarize status.\" class=\"w-full bg-slate-900 border border-slate-700 rounded-lg p-2.5 text-xs text-white\"></textarea>\n          </div>\n          <button type=\"submit\" class=\"w-full py-2 bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-semibold rounded-lg\">+ Schedule Cron Job</button>\n        </form>\n        <div class=\"pt-3 border-t border-slate-800 space-y-2\">\n          <div class=\"text-xs font-bold text-slate-300\">\u26a1 One-Click Blueprints</div>\n          <button type=\"button\" onclick=\"fillCronBlueprint('Spot VM /data Health Audit', '*/30 * * * *', 'Run df -h /data and check systemctl is-active for hermes services, then report health.')\" class=\"w-full text-left p-2 rounded-lg bg-slate-900 hover:bg-slate-800 border border-slate-800 text-xs text-slate-200\">\ud83d\udee1\ufe0f Spot VM /data Health Audit (Every 30m)</button>\n          <button type=\"button\" onclick=\"fillCronBlueprint('AI Research Digest', '0 8 * * *', 'Search the web for the latest LLM and agent breakthroughs today and save key findings to memory.')\" class=\"w-full text-left p-2 rounded-lg bg-slate-900 hover:bg-slate-800 border border-slate-800 text-xs text-slate-200\">\ud83d\udd2c Daily AI Research Digest (8:00 AM)</button>\n        </div>\n      </div>\n      <div class=\"flex-1 p-4 overflow-y-auto space-y-3\" id=\"cronJobsContainer\"></div>\n    </div>\n\n    <!-- ==================== TAB 8: /data FILE EXPLORER ==================== -->\n    <div id=\"tab-files\" class=\"hidden flex-1 flex flex-col md:flex-row overflow-hidden bg-[#060911]\">\n      <div class=\"w-full md:w-80 border-b md:border-b-0 md:border-r border-slate-800 bg-[#0a0f1c] flex flex-col max-h-60 md:max-h-none\">\n        <div class=\"p-3 border-b border-slate-800 space-y-2\">\n          <div class=\"flex gap-1\">\n            <input id=\"filePathInput\" type=\"text\" value=\"/data/hermes\" class=\"flex-1 bg-slate-900 border border-slate-700 rounded-lg px-2.5 py-1.5 text-xs font-mono text-white\" />\n            <button type=\"button\" onclick=\"browseFiles()\" class=\"px-2.5 py-1.5 bg-indigo-600 text-white text-xs rounded-lg\">Go</button>\n            <button type=\"button\" onclick=\"browseParentDir()\" class=\"px-2 py-1.5 bg-slate-800 text-slate-300 text-xs rounded-lg\">\u2191</button>\n          </div>\n          <div class=\"flex gap-1\">\n            <input id=\"fileSearchQuery\" type=\"text\" placeholder=\"Grep search in /data/hermes...\" class=\"flex-1 bg-slate-900 border border-slate-700 rounded-lg px-2.5 py-1 text-xs text-white\" />\n            <button type=\"button\" onclick=\"grepFilesUI()\" class=\"px-2.5 py-1 bg-emerald-600 text-white text-xs rounded-lg\">Grep</button>\n          </div>\n        </div>\n        <div id=\"fileTreeList\" class=\"flex-1 overflow-y-auto p-2 space-y-1 font-mono text-xs\"></div>\n      </div>\n      <div class=\"flex-1 flex flex-col overflow-hidden\">\n        <div class=\"p-3 bg-[#0a0f1c] border-b border-slate-800 flex items-center justify-between\">\n          <span id=\"openFilePath\" class=\"text-xs font-mono text-sky-300\">/data/hermes/boot.sh</span>\n          <button type=\"button\" onclick=\"saveOpenFile()\" class=\"px-3 py-1.5 bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-semibold rounded-lg\">\ud83d\udcbe Save File to /data</button>\n        </div>\n        <textarea id=\"fileEditorContent\" class=\"flex-1 bg-[#050811] p-4 font-mono text-xs text-slate-100 focus:outline-none resize-none\"></textarea>\n      </div>\n    </div>\n\n    <!-- ==================== TAB 9: SYSTEM, DOCTOR & ANALYTICS ==================== -->\n    <div id=\"tab-system\" class=\"hidden flex-1 p-4 md:p-5 overflow-y-auto bg-[#060911] space-y-5\">\n      <div class=\"grid grid-cols-1 md:grid-cols-4 gap-3\" id=\"systemStatsCards\"></div>\n      <div class=\"grid grid-cols-1 md:grid-cols-2 gap-4\">\n        <div class=\"bg-[#0a0f1c] border border-slate-800 rounded-xl p-4 space-y-3\">\n          <div class=\"flex flex-wrap items-center justify-between gap-2\">\n            <h3 class=\"text-sm font-bold text-white\">\ud83e\ude7a Hermes Doctor & CLI Diagnostics</h3>\n            <div class=\"flex gap-1.5\">\n              <button type=\"button\" onclick=\"runHermesDoctor('status')\" class=\"px-2.5 py-1 bg-indigo-600 hover:bg-indigo-500 text-white text-xs rounded\">hermes status</button>\n              <button type=\"button\" onclick=\"runHermesDoctor('doctor')\" class=\"px-2.5 py-1 bg-emerald-600 hover:bg-emerald-500 text-white text-xs rounded\">hermes doctor</button>\n              <button type=\"button\" onclick=\"runHermesDoctor('config show')\" class=\"px-2.5 py-1 bg-slate-800 hover:bg-slate-700 text-slate-200 text-xs rounded\">config show</button>\n            </div>\n          </div>\n          <pre id=\"doctorOutput\" class=\"bg-[#04070e] border border-slate-800 rounded-lg p-3 font-mono text-xs text-emerald-300 h-72 overflow-y-auto whitespace-pre-wrap\">Click \"hermes doctor\" or \"hermes status\" to run live diagnostics on the Spot VM.</pre>\n        </div>\n        <div class=\"bg-[#0a0f1c] border border-slate-800 rounded-xl p-4 space-y-3\">\n          <div class=\"flex items-center justify-between\">\n            <h3 class=\"text-sm font-bold text-white\">\u2699\ufe0f Spot VM Services & Persistent /data Telemetry</h3>\n            <button type=\"button\" onclick=\"loadSystemOverview()\" class=\"px-2.5 py-1 bg-slate-800 hover:bg-slate-700 text-slate-200 text-xs rounded\">\u21bb Refresh</button>\n          </div>\n          <pre id=\"processesOutput\" class=\"bg-[#04070e] border border-slate-800 rounded-lg p-3 font-mono text-xs text-sky-300 h-72 overflow-y-auto whitespace-pre-wrap\">Loading Spot VM telemetry...</pre>\n        </div>\n      </div>\n    </div>\n\n  </div>\n\n  <script>\n    // ========================================================================\n    // HERMES AGENT WEB WORKSPACE CONTROLLER (Mobile + Desktop + Background)\n    // ========================================================================\n    var authToken = localStorage.getItem('hermes_auth_token') || '';\n    var activeSessionId = localStorage.getItem('hermes_active_session') || '';\n    var sessions = [];\n    var models = [];\n    var skills = [];\n    var selectedSkillName = '';\n    var preloadedSkill = '';\n    var activeGoal = '';\n    var attachedImage = null;\n    var bgMode = localStorage.getItem('hermes_bg_mode') !== 'false';\n    var activeTab = 'chat';\n    var pollTimer = null;\n    var isPolling = false;\n\n    var FALLBACK_MODELS = [\n      { id: 'gemini-3.8-flash', name: 'Gemini 3.8 Flash (Default Fast)', tier: '3.8 Preview', thinking: true },\n      { id: 'gemini-3.8-flash-thinking', name: 'Gemini 3.8 Flash [Thinking Mode]', tier: '3.8 Thinking', thinking: true },\n      { id: 'gemini-3.8-pro-preview', name: 'Gemini 3.8 Pro Preview (Flagship)', tier: '3.8 Preview', thinking: true },\n      { id: 'gemini-3.8-pro-preview-thinking', name: 'Gemini 3.8 Pro Preview [Deep Thinking]', tier: '3.8 Thinking', thinking: true },\n      { id: 'gemini-3.8-flash-lite-preview', name: 'Gemini 3.8 Flash-Lite Preview', tier: '3.8 Preview', thinking: true },\n      { id: 'gemini-3.8-flash-lite-preview-thinking', name: 'Gemini 3.8 Flash-Lite [Thinking]', tier: '3.8 Thinking', thinking: true },\n      { id: 'gemini-3.1-pro-preview', name: 'Gemini 3.1 Pro Preview', tier: '3.1 Preview', thinking: true },\n      { id: 'gemini-3.1-pro-preview-thinking', name: 'Gemini 3.1 Pro Preview [Deep Thinking]', tier: '3.1 Thinking', thinking: true },\n      { id: 'gemini-3.1-flash-lite-preview', name: 'Gemini 3.1 Flash-Lite Preview', tier: '3.1 Preview', thinking: true },\n      { id: 'gemini-3.1-flash-lite-preview-thinking', name: 'Gemini 3.1 Flash-Lite [Thinking]', tier: '3.1 Thinking', thinking: true },\n      { id: 'gemini-3-pro-preview', name: 'Gemini 3.0 Pro Preview', tier: '3.0 Preview', thinking: true },\n      { id: 'gemini-3-pro-preview-thinking', name: 'Gemini 3.0 Pro Preview [Deep Thinking]', tier: '3.0 Thinking', thinking: true },\n      { id: 'gemini-3-flash-preview', name: 'Gemini 3.0 Flash Preview', tier: '3.0 Preview', thinking: true },\n      { id: 'gemini-3-flash-preview-thinking', name: 'Gemini 3.0 Flash Preview [Thinking]', tier: '3.0 Thinking', thinking: true },\n      { id: 'gemini-2.5-pro', name: 'Gemini 2.5 Pro (Production)', tier: '2.5 GA', thinking: true },\n      { id: 'gemini-2.5-pro-thinking', name: 'Gemini 2.5 Pro [Max Thinking 24K]', tier: '2.5 Thinking', thinking: true },\n      { id: 'gemini-2.5-flash', name: 'Gemini 2.5 Flash (Production)', tier: '2.5 GA', thinking: true },\n      { id: 'gemini-2.5-flash-thinking', name: 'Gemini 2.5 Flash [Thinking Mode]', tier: '2.5 Thinking', thinking: true },\n      { id: 'gemini-2.5-flash-lite', name: 'Gemini 2.5 Flash-Lite', tier: '2.5 GA', thinking: true },\n      { id: 'gemini-2.0-flash', name: 'Gemini 2.0 Flash', tier: '2.0 GA', thinking: false },\n      { id: 'gemini-2.0-flash-lite', name: 'Gemini 2.0 Flash-Lite', tier: '2.0 GA', thinking: false }\n    ];\n\n    var SLASH_COMMANDS = [\n      { cmd: '/help', desc: 'Show all Hermes slash commands, 19 tools & capabilities', immediate: true },\n      { cmd: '/doctor', desc: 'Run live hermes doctor & Spot VM /data diagnostics', immediate: true },\n      { cmd: '/status', desc: 'Inspect Spot VM bridge, systemd services & /data disk', immediate: true },\n      { cmd: '/moa ', desc: 'Mixture-of-Agents: Parallel synthesis across 3 Gemini flagship models', immediate: false },\n      { cmd: '/learn', desc: 'Extract a reusable SKILL.md from this conversation into /data/hermes', immediate: true },\n      { cmd: '/goal ', desc: 'Set a standing autonomous goal for this session', immediate: false },\n      { cmd: '/model ', desc: 'Switch active Gemini model (e.g. /model gemini-3.8-pro-preview-thinking)', immediate: false },\n      { cmd: '/thinking ', desc: 'Set thinking budget (auto, off, low, medium, high, max)', immediate: false },\n      { cmd: '/tools ', desc: 'Switch active toolset (hermes-cli, coding, web, debugging, safe, off)', immediate: false },\n      { cmd: '/compress', desc: 'Compress & summarize long conversation history', immediate: true },\n      { cmd: '/usage', desc: 'View session token & message analytics', immediate: true },\n      { cmd: '/retry', desc: 'Re-run the last user request', immediate: true },\n      { cmd: '/undo', desc: 'Undo the last user/assistant turn', immediate: true },\n      { cmd: '/clear', desc: 'Clear messages in the current session', immediate: true },\n      { cmd: '/new', desc: 'Start a fresh session', immediate: true },\n      { cmd: '/jobs', desc: 'Open Background Jobs Monitor tab', immediate: true },\n      { cmd: '/skills', desc: 'Open 60+ Skills Hub tab', immediate: true },\n      { cmd: '/memory', desc: 'Open SOUL.md, MEMORY.md & USER.md editor tab', immediate: true },\n      { cmd: '/kanban', desc: 'Open Multi-Agent Kanban Board tab', immediate: true },\n      { cmd: '/cron', desc: 'Open Scheduled Cron Automations tab', immediate: true }\n    ];\n\n    function esc(s) {\n      return String(s == null ? '' : s)\n        .replace(/&/g, '&amp;')\n        .replace(/</g, '&lt;')\n        .replace(/>/g, '&gt;')\n        .replace(/\"/g, '&quot;');\n    }\n\n    function renderMd(text) {\n      if (!text) return '';\n      try {\n        if (window.marked && typeof window.marked.parse === 'function') {\n          return window.marked.parse(String(text));\n        }\n      } catch (e) {}\n      return '<pre class=\"whitespace-pre-wrap text-xs\">' + esc(text) + '</pre>';\n    }\n\n    async function api(path, opts) {\n      opts = opts || {};\n      var headers = Object.assign({ 'Content-Type': 'application/json' }, opts.headers || {});\n      if (authToken) {\n        headers['Authorization'] = 'Bearer ' + authToken;\n      }\n      var res = await fetch(path, Object.assign({}, opts, { headers: headers }));\n      if (res.status === 401) {\n        document.getElementById('loginOverlay').classList.remove('hidden');\n        throw new Error('Unauthorized');\n      }\n      var data = await res.json().catch(function() { return { ok: false, error: 'Invalid JSON response' }; });\n      return data;\n    }\n\n    // ------------------------------------------------------------------------\n    // AUTHENTICATION\n    // ------------------------------------------------------------------------\n    async function submitLogin(e) {\n      if (e) e.preventDefault();\n      var u = document.getElementById('loginUsername').value.trim();\n      var p = document.getElementById('loginPassword').value;\n      var errEl = document.getElementById('loginError');\n      var btn = document.getElementById('loginBtn');\n      errEl.classList.add('hidden');\n      btn.disabled = true;\n      btn.textContent = 'Unlocking...';\n      try {\n        var res = await fetch('/api/login', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ username: u, password: p })\n        });\n        var data = await res.json();\n        if (!res.ok || !data.ok || !data.token) {\n          throw new Error(data.error || 'Invalid credentials');\n        }\n        authToken = data.token;\n        localStorage.setItem('hermes_auth_token', authToken);\n        document.getElementById('loginOverlay').classList.add('hidden');\n        await bootWorkspace();\n      } catch (err) {\n        errEl.textContent = err.message || 'Login failed';\n        errEl.classList.remove('hidden');\n      } finally {\n        btn.disabled = false;\n        btn.textContent = 'Unlock Hermes Workspace';\n      }\n    }\n\n    async function logout() {\n      try { await api('/api/logout', { method: 'POST' }); } catch (e) {}\n      authToken = '';\n      localStorage.removeItem('hermes_auth_token');\n      document.getElementById('loginOverlay').classList.remove('hidden');\n    }\n\n    // ------------------------------------------------------------------------\n    // MODELS, THINKING, TOOLSET & BACKGROUND KEEP-ALIVE CONTROLS\n    // ------------------------------------------------------------------------\n    function populateModelDropdown(list) {\n      models = (Array.isArray(list) && list.length > 0) ? list : FALLBACK_MODELS;\n      var sel = document.getElementById('modelSelect');\n      if (!sel) return;\n      var savedModel = localStorage.getItem('hermes_selected_model') || 'gemini-3.8-flash';\n      var html = '';\n      for (var i = 0; i < models.length; i++) {\n        var m = models[i];\n        var rawName = m.name || m.id;\n        var hasIcon = (rawName.indexOf('\ud83e\udde0') === 0 || rawName.indexOf('\u2726') === 0);\n        var badge = hasIcon ? '' : ((m.id.indexOf('-thinking') !== -1) ? '\ud83e\udde0 ' : '\u2726 ');\n        var tier = m.tier ? ' [' + m.tier + ']' : '';\n        html += '<option value=\"' + esc(m.id) + '\">' + badge + esc(rawName) + esc(tier) + '</option>';\n      }\n      sel.innerHTML = html;\n      var exists = models.some(function(m) { return m.id === savedModel; });\n      sel.value = exists ? savedModel : models[0].id;\n    }\n\n    async function loadModels() {\n      populateModelDropdown(FALLBACK_MODELS);\n      try {\n        var data = await api('/api/models');\n        if (data && Array.isArray(data.models) && data.models.length > 0) {\n          populateModelDropdown(data.models);\n        }\n      } catch (e) {}\n    }\n\n    async function onModelChange() {\n      var val = document.getElementById('modelSelect').value;\n      localStorage.setItem('hermes_selected_model', val);\n      if (val.indexOf('-thinking') !== -1 && document.getElementById('thinkingSelect').value === 'off') {\n        document.getElementById('thinkingSelect').value = 'high';\n      }\n      if (activeSessionId) {\n        try {\n          await api('/api/sessions/' + encodeURIComponent(activeSessionId), {\n            method: 'PATCH',\n            body: JSON.stringify({ model: val })\n          });\n        } catch (e) {}\n      }\n    }\n\n    async function onThinkingChange() {\n      var val = document.getElementById('thinkingSelect').value;\n      localStorage.setItem('hermes_thinking_level', val);\n      if (activeSessionId) {\n        try {\n          await api('/api/sessions/' + encodeURIComponent(activeSessionId), {\n            method: 'PATCH',\n            body: JSON.stringify({ thinking_level: val })\n          });\n        } catch (e) {}\n      }\n    }\n\n    async function onToolsetChange() {\n      var val = document.getElementById('toolsetSelect').value;\n      localStorage.setItem('hermes_toolset', val);\n      if (activeSessionId) {\n        try {\n          await api('/api/sessions/' + encodeURIComponent(activeSessionId), {\n            method: 'PATCH',\n            body: JSON.stringify({ toolset: val })\n          });\n        } catch (e) {}\n      }\n    }\n\n    function updateBgModeButton() {\n      var btn = document.getElementById('bgModeBtn');\n      if (!btn) return;\n      if (bgMode) {\n        btn.textContent = '\ud83d\udd04 Keep-Alive: ON';\n        btn.className = 'text-[11px] px-2.5 py-1.5 rounded-lg bg-emerald-600/25 border border-emerald-500/50 text-emerald-200 font-semibold whitespace-nowrap';\n      } else {\n        btn.textContent = '\u26a1 Sync Mode';\n        btn.className = 'text-[11px] px-2.5 py-1.5 rounded-lg bg-slate-800 border border-slate-700 text-slate-300 font-semibold whitespace-nowrap';\n      }\n    }\n\n    function toggleBgMode() {\n      bgMode = !bgMode;\n      localStorage.setItem('hermes_bg_mode', bgMode ? 'true' : 'false');\n      updateBgModeButton();\n    }\n\n    // ------------------------------------------------------------------------\n    // NAVIGATION & MOBILE DRAWER\n    // ------------------------------------------------------------------------\n    function toggleMobileSidebar() {\n      var sb = document.getElementById('sessionSidebar');\n      if (!sb) return;\n      if (sb.classList.contains('hidden')) {\n        sb.classList.remove('hidden');\n        sb.classList.add('flex');\n      } else {\n        sb.classList.add('hidden');\n        sb.classList.remove('flex');\n      }\n    }\n\n    function switchTab(tab) {\n      activeTab = tab;\n      var allTabs = ['chat', 'jobs', 'terminal', 'skills', 'memory', 'kanban', 'cron', 'files', 'system'];\n      for (var i = 0; i < allTabs.length; i++) {\n        var t = allTabs[i];\n        var pane = document.getElementById('tab-' + t);\n        var btn = document.getElementById('tabBtn-' + t);\n        if (pane) {\n          if (t === tab) pane.classList.remove('hidden');\n          else pane.classList.add('hidden');\n        }\n        if (btn) {\n          if (t === tab) btn.classList.add('active');\n          else btn.classList.remove('active');\n        }\n      }\n      if (tab === 'jobs') loadJobsTab();\n      else if (tab === 'skills') loadSkillsTab();\n      else if (tab === 'memory') loadMemoryTab();\n      else if (tab === 'kanban') loadKanbanTab();\n      else if (tab === 'cron') loadCronTab();\n      else if (tab === 'files') browseFiles();\n      else if (tab === 'system') loadSystemOverview();\n    }\n\n    // ------------------------------------------------------------------------\n    // SESSIONS & UNSTOPPABLE BACKGROUND POLLER\n    // ------------------------------------------------------------------------\n    async function loadSessions() {\n      try {\n        var data = await api('/api/sessions');\n        sessions = data.sessions || [];\n        renderSessionList();\n        if (!activeSessionId && sessions.length > 0) {\n          await selectSession(sessions[0].id);\n        } else if (activeSessionId) {\n          await selectSession(activeSessionId);\n        } else {\n          await createNewSession();\n        }\n      } catch (e) {}\n    }\n\n    function filterSessions() {\n      renderSessionList();\n    }\n\n    function renderSessionList() {\n      var q = (document.getElementById('sessionSearchInput') ? document.getElementById('sessionSearchInput').value : '').toLowerCase();\n      var el = document.getElementById('sessionList');\n      if (!el) return;\n      var html = '';\n      for (var i = 0; i < sessions.length; i++) {\n        var s = sessions[i];\n        if (q && (s.title || '').toLowerCase().indexOf(q) === -1 && (s.last_preview || '').toLowerCase().indexOf(q) === -1) {\n          continue;\n        }\n        var isAct = s.id === activeSessionId;\n        var cls = isAct\n          ? 'bg-indigo-600/20 border-indigo-500/50 text-white'\n          : 'bg-slate-900/60 hover:bg-slate-800/80 border-slate-800/80 text-slate-300';\n        html += '<div class=\"group flex items-center justify-between p-2 rounded-xl border cursor-pointer transition ' + cls + '\" onclick=\"selectSession(\\'' + esc(s.id) + '\\')\">'\n          + '<div class=\"min-w-0 flex-1 pr-2\">'\n          + '<div class=\"text-xs font-semibold truncate\">' + esc(s.title || 'Session') + '</div>'\n          + '<div class=\"text-[10px] text-slate-400 font-mono truncate\">' + esc(s.model || 'gemini-3.8-flash') + ' \u2022 ' + (s.message_count || 0) + ' msgs</div>'\n          + '</div>'\n          + '<button type=\"button\" onclick=\"event.stopPropagation(); deleteSession(\\'' + esc(s.id) + '\\')\" class=\"opacity-60 hover:opacity-100 text-xs text-slate-400 hover:text-red-400 px-1.5 py-0.5\">\u2715</button>'\n          + '</div>';\n      }\n      el.innerHTML = html || '<div class=\"text-xs text-slate-500 p-3 text-center\">No sessions yet</div>';\n    }\n\n    async function selectSession(id) {\n      activeSessionId = id;\n      localStorage.setItem('hermes_active_session', id);\n      renderSessionList();\n      try {\n        var data = await api('/api/sessions/' + encodeURIComponent(id));\n        var sess = data.session || data;\n        if (sess.model && document.getElementById('modelSelect')) {\n          document.getElementById('modelSelect').value = sess.model;\n        }\n        if (sess.thinking_level && document.getElementById('thinkingSelect')) {\n          document.getElementById('thinkingSelect').value = sess.thinking_level;\n        }\n        if (sess.toolset && document.getElementById('toolsetSelect')) {\n          document.getElementById('toolsetSelect').value = sess.toolset;\n        }\n        activeGoal = sess.goal || '';\n        updateGoalBanner();\n        renderMessages(sess.messages || []);\n        updateRunningBanner(sess.messages || []);\n      } catch (e) {}\n    }\n\n    async function createNewSession() {\n      try {\n        var model = document.getElementById('modelSelect') ? document.getElementById('modelSelect').value : 'gemini-3.8-flash';\n        var thinking = document.getElementById('thinkingSelect') ? document.getElementById('thinkingSelect').value : 'auto';\n        var toolset = document.getElementById('toolsetSelect') ? document.getElementById('toolsetSelect').value : 'hermes-cli';\n        var data = await api('/api/sessions', {\n          method: 'POST',\n          body: JSON.stringify({ title: 'Hermes Session', model: model, thinking_level: thinking, toolset: toolset })\n        });\n        if (data.session) {\n          sessions.unshift({\n            id: data.session.id,\n            title: data.session.title,\n            model: data.session.model,\n            thinking_level: data.session.thinking_level,\n            toolset: data.session.toolset,\n            updated_at: data.session.updated_at,\n            message_count: 0\n          });\n          await selectSession(data.session.id);\n        }\n      } catch (e) {}\n    }\n\n    async function deleteSession(id) {\n      try {\n        await api('/api/sessions/' + encodeURIComponent(id), { method: 'DELETE' });\n        sessions = sessions.filter(function(s) { return s.id !== id; });\n        if (activeSessionId === id) {\n          activeSessionId = sessions.length > 0 ? sessions[0].id : '';\n        }\n        if (activeSessionId) await selectSession(activeSessionId);\n        else await createNewSession();\n      } catch (e) {}\n    }\n\n    function updateRunningBanner(msgs) {\n      var hasRunning = (msgs || []).some(function(m) { return m.status === 'running'; });\n      var banner = document.getElementById('liveBgBanner');\n      var badge = document.getElementById('bgJobsBadge');\n      if (banner) {\n        if (hasRunning) banner.classList.remove('hidden');\n        else banner.classList.add('hidden');\n      }\n      if (badge) {\n        if (hasRunning) {\n          badge.textContent = '\u26a1 BG: Running...';\n          badge.className = 'text-[10px] px-2 py-0.5 rounded bg-amber-500/20 text-amber-300 border border-amber-500/40 font-mono animate-pulse';\n        } else {\n          badge.textContent = '\u26a1 BG: Ready';\n          badge.className = 'text-[10px] px-2 py-0.5 rounded bg-indigo-500/15 text-indigo-300 border border-indigo-500/30 font-mono hover:bg-indigo-500/25';\n        }\n      }\n    }\n\n    async function pollActiveSession(forceRender) {\n      if (isPolling || !authToken || !activeSessionId) return;\n      isPolling = true;\n      try {\n        var data = await api('/api/sessions/' + encodeURIComponent(activeSessionId));\n        var sess = data.session || data;\n        var msgs = sess.messages || [];\n        var hasRunning = msgs.some(function(m) { return m.status === 'running'; });\n        updateRunningBanner(msgs);\n        if (forceRender || hasRunning || window._wasRunningLastPoll) {\n          renderMessages(msgs);\n          loadSessionsQuiet();\n        }\n        window._wasRunningLastPoll = hasRunning;\n      } catch (e) {\n      } finally {\n        isPolling = false;\n      }\n    }\n\n    async function loadSessionsQuiet() {\n      try {\n        var data = await api('/api/sessions');\n        if (data && data.sessions) {\n          sessions = data.sessions;\n          renderSessionList();\n        }\n        var jData = await api('/api/jobs');\n        if (jData && Array.isArray(jData.jobs)) {\n          var runningCount = jData.jobs.filter(function(j) { return j.status === 'running'; }).length;\n          var navCount = document.getElementById('navJobCount');\n          if (navCount) navCount.textContent = String(runningCount || jData.jobs.length || 0);\n        }\n      } catch (e) {}\n    }\n\n    function startBackgroundPoller() {\n      if (pollTimer) clearInterval(pollTimer);\n      pollTimer = setInterval(function() {\n        pollActiveSession(false);\n        var jobsTab = document.getElementById('tab-jobs');\n        if (jobsTab && !jobsTab.classList.contains('hidden')) { loadJobsTab(); }\n      }, 2200);\n      document.addEventListener('visibilitychange', function() {\n        if (document.visibilityState === 'visible') {\n          pollActiveSession(true);\n          loadSessionsQuiet();\n        }\n      });\n      window.addEventListener('focus', function() {\n        pollActiveSession(true);\n      });\n    }\n\n    // ------------------------------------------------------------------------\n    // SLASH COMMAND POPUP & QUICK ACTIONS\n    // ------------------------------------------------------------------------\n    function renderSlashPopup(filterText) {\n      var popup = document.getElementById('slashPopup');\n      if (!popup) return;\n      var q = (filterText || '').toLowerCase();\n      var matches = SLASH_COMMANDS.filter(function(c) {\n        return !q || c.cmd.toLowerCase().indexOf(q) !== -1 || c.desc.toLowerCase().indexOf(q) !== -1;\n      });\n      if (matches.length === 0) {\n        popup.classList.add('hidden');\n        return;\n      }\n      var html = '<div class=\"text-[10px] font-bold uppercase tracking-wider text-indigo-300 px-2.5 py-1 border-b border-slate-800 flex items-center justify-between\">'\n        + '<span>\u2624 Hermes Slash Commands (Tap to run)</span>'\n        + '<button type=\"button\" onclick=\"closeSlashMenu()\" class=\"text-slate-400 hover:text-white\">\u2715</button>'\n        + '</div><div class=\"divide-y divide-slate-800/60\">';\n      for (var i = 0; i < matches.length; i++) {\n        var item = matches[i];\n        html += '<button type=\"button\" onclick=\"pickSlashCommand(\\'' + esc(item.cmd) + '\\', ' + (item.immediate ? 'true' : 'false') + ')\" '\n          + 'class=\"w-full text-left px-3 py-2 hover:bg-indigo-600/20 flex items-center justify-between gap-2 transition\">'\n          + '<span class=\"font-mono text-xs font-bold text-indigo-300\">' + esc(item.cmd) + '</span>'\n          + '<span class=\"text-xs text-slate-400 truncate\">' + esc(item.desc) + '</span>'\n          + '</button>';\n      }\n      html += '</div>';\n      popup.innerHTML = html;\n      popup.classList.remove('hidden');\n    }\n\n    function toggleSlashMenu() {\n      var popup = document.getElementById('slashPopup');\n      if (!popup) return;\n      if (popup.classList.contains('hidden')) {\n        renderSlashPopup('');\n      } else {\n        popup.classList.add('hidden');\n      }\n    }\n\n    function closeSlashMenu() {\n      var popup = document.getElementById('slashPopup');\n      if (popup) popup.classList.add('hidden');\n    }\n\n    function onChatInput() {\n      var inp = document.getElementById('chatInput');\n      if (!inp) return;\n      var val = inp.value;\n      if (val.indexOf('/') === 0 && val.indexOf('\\n') === -1 && val.length < 25) {\n        renderSlashPopup(val.trim());\n      } else {\n        closeSlashMenu();\n      }\n    }\n\n    function pickSlashCommand(cmd, immediate) {\n      closeSlashMenu();\n      var inp = document.getElementById('chatInput');\n      if (!inp) return;\n      if (immediate) {\n        inp.value = cmd.trim();\n        sendMessage(null);\n      } else {\n        inp.value = cmd;\n        inp.focus();\n      }\n    }\n\n    function runQuickSlash(cmd) {\n      var inp = document.getElementById('chatInput');\n      if (!inp) return;\n      inp.value = cmd;\n      sendMessage(null);\n    }\n\n    // ------------------------------------------------------------------------\n    // CHAT STREAM, MULTIMODAL VISION & VOICE\n    // ------------------------------------------------------------------------\n    function updateGoalBanner() {\n      var b = document.getElementById('goalBanner');\n      var t = document.getElementById('goalText');\n      if (!b || !t) return;\n      if (activeGoal) {\n        t.textContent = activeGoal;\n        b.classList.remove('hidden');\n      } else {\n        b.classList.add('hidden');\n      }\n    }\n\n    async function setGoal(g) {\n      activeGoal = g;\n      updateGoalBanner();\n      if (activeSessionId) {\n        try {\n          await api('/api/sessions/' + encodeURIComponent(activeSessionId), {\n            method: 'PATCH',\n            body: JSON.stringify({ goal: g })\n          });\n        } catch (e) {}\n      }\n    }\n\n    function clearPreloadedSkill() {\n      preloadedSkill = '';\n      var b = document.getElementById('activeSkillBanner');\n      if (b) b.classList.add('hidden');\n    }\n\n    function handleImageUpload(e) {\n      var file = e.target.files && e.target.files[0];\n      if (!file) return;\n      var reader = new FileReader();\n      reader.onload = function(ev) {\n        var dataUrl = String(ev.target.result || '');\n        var commaIdx = dataUrl.indexOf(',');\n        attachedImage = {\n          name: file.name,\n          mimeType: file.type || 'image/png',\n          data: commaIdx !== -1 ? dataUrl.slice(commaIdx + 1) : dataUrl\n        };\n        document.getElementById('imagePreviewName').textContent = file.name;\n        document.getElementById('imagePreviewBar').classList.remove('hidden');\n      };\n      reader.readAsDataURL(file);\n    }\n\n    function clearImageAttachment() {\n      attachedImage = null;\n      var inp = document.getElementById('imageInput');\n      if (inp) inp.value = '';\n      document.getElementById('imagePreviewBar').classList.add('hidden');\n    }\n\n    function toggleVoiceInput() {\n      var SR = window.SpeechRecognition || window.webkitSpeechRecognition;\n      if (!SR) {\n        alert('Speech recognition is not supported in this browser.');\n        return;\n      }\n      var rec = new SR();\n      rec.lang = 'en-US';\n      rec.onresult = function(ev) {\n        var t = ev.results[0][0].transcript;\n        var inp = document.getElementById('chatInput');\n        inp.value = (inp.value ? inp.value + ' ' : '') + t;\n      };\n      rec.start();\n    }\n\n    function speakText(btn) {\n      var txt = btn.getAttribute('data-speech') || '';\n      if (!txt || !window.speechSynthesis) return;\n      window.speechSynthesis.cancel();\n      var u = new SpeechSynthesisUtterance(txt.slice(0, 800));\n      window.speechSynthesis.speak(u);\n    }\n\n    function renderMessages(msgs) {\n      var container = document.getElementById('chatMessages');\n      if (!container) return;\n      if (!msgs || msgs.length === 0) {\n        container.innerHTML = '<div class=\"max-w-3xl mx-auto my-6 p-6 rounded-2xl bg-[#0b1120] border border-slate-800/90 space-y-4\">'\n          + '<div class=\"flex items-center gap-3\">'\n          + '<div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-amber-500 via-indigo-500 to-purple-600 flex items-center justify-center font-bold text-lg text-white\">\u2624</div>'\n          + '<div>'\n          + '<h2 class=\"font-bold text-base text-white\">Hermes Agent \u2624 \u2014 End-to-End Autonomous Workspace</h2>'\n          + '<p class=\"text-xs text-slate-400\">21 Google Vertex AI Models \u2022 19 Live Tools on Spot VM (/data/hermes) \u2022 Unstoppable Background Mode</p>'\n          + '</div></div>'\n          + '<div class=\"grid grid-cols-1 md:grid-cols-2 gap-2.5 text-xs\">'\n          + '<button type=\"button\" onclick=\"runQuickSlash(\\'Check /data disk usage, list /data/hermes files, and verify all 3 systemd services are active.\\')\" class=\"text-left p-3 rounded-xl bg-slate-900/90 hover:bg-slate-800 border border-slate-800 text-slate-200\">'\n          + '<div class=\"font-bold text-emerald-400 mb-0.5\">\ud83d\udcbb Spot VM & /data Live Audit</div>'\n          + '<div class=\"text-slate-400\">Execute bash commands on /data/hermes and verify persistence</div></button>'\n          + '<button type=\"button\" onclick=\"runQuickSlash(\\'/moa Design a fault-tolerant distributed agent architecture on Spot VMs.\\')\" class=\"text-left p-3 rounded-xl bg-slate-900/90 hover:bg-slate-800 border border-slate-800 text-slate-200\">'\n          + '<div class=\"font-bold text-purple-400 mb-0.5\">\ud83e\uddec /moa Mixture-of-Agents</div>'\n          + '<div class=\"text-slate-400\">Parallel synthesis across Gemini 3.8 Pro, 3.8 Flash & 3.1 Pro</div></button>'\n          + '<button type=\"button\" onclick=\"runQuickSlash(\\'/doctor\\')\" class=\"text-left p-3 rounded-xl bg-slate-900/90 hover:bg-slate-800 border border-slate-800 text-slate-200\">'\n          + '<div class=\"font-bold text-sky-400 mb-0.5\">\ud83e\ude7a /doctor Diagnostics</div>'\n          + '<div class=\"text-slate-400\">Verify all 21 Vertex AI models, 19 tools, R2 & SQLite sync</div></button>'\n          + '<button type=\"button\" onclick=\"runQuickSlash(\\'/help\\')\" class=\"text-left p-3 rounded-xl bg-slate-900/90 hover:bg-slate-800 border border-slate-800 text-slate-200\">'\n          + '<div class=\"font-bold text-amber-400 mb-0.5\">\u26a1 /help Slash Commands</div>'\n          + '<div class=\"text-slate-400\">Inspect all slash commands, background mode & toolsets</div></button>'\n          + '</div></div>';\n        return;\n      }\n\n      var html = '';\n      for (var i = 0; i < msgs.length; i++) {\n        var m = msgs[i];\n        if (m.role === 'user') {\n          html += '<div class=\"flex justify-end\">'\n            + '<div class=\"max-w-3xl bg-indigo-600/25 border border-indigo-500/40 rounded-2xl rounded-tr-sm px-4 py-3 text-sm text-slate-100\">'\n            + (m.has_image ? '<div class=\"text-xs text-sky-300 mb-1 font-mono\">\ud83d\uddbc\ufe0f [Image Attached]</div>' : '')\n            + '<div class=\"whitespace-pre-wrap\">' + esc(m.content) + '</div>'\n            + '</div></div>';\n        } else {\n          var isRun = m.status === 'running';\n          var thoughtsHtml = '';\n          if (Array.isArray(m.thoughts) && m.thoughts.length > 0) {\n            thoughtsHtml = '<details class=\"thinking-box rounded-lg p-2.5 mb-2.5 text-xs text-purple-200\">'\n              + '<summary class=\"cursor-pointer font-semibold text-purple-300\">\ud83e\udde0 Thinking Trace (' + m.thoughts.length + ' step' + (m.thoughts.length > 1 ? 's' : '') + ')</summary>'\n              + '<div class=\"mt-2 space-y-1.5 font-mono text-[11px] whitespace-pre-wrap text-purple-100/90\">'\n              + esc(m.thoughts.join('\\n\\n'))\n              + '</div></details>';\n          }\n          var toolsHtml = '';\n          if (Array.isArray(m.tool_calls) && m.tool_calls.length > 0) {\n            toolsHtml = '<details class=\"tool-box rounded-lg p-2.5 mb-2.5 text-xs text-emerald-200\" ' + (isRun ? 'open' : '') + '>'\n              + '<summary class=\"cursor-pointer font-semibold text-emerald-300\">\ud83d\udee0\ufe0f Executed ' + m.tool_calls.length + ' Hermes Tool' + (m.tool_calls.length > 1 ? 's' : '') + ' on Spot VM (/data/hermes)</summary>'\n              + '<div class=\"mt-2 space-y-2\">';\n            for (var j = 0; j < m.tool_calls.length; j++) {\n              var tc = m.tool_calls[j];\n              toolsHtml += '<div class=\"bg-slate-950/80 border border-slate-800 rounded p-2 font-mono text-[11px]\">'\n                + '<div class=\"text-emerald-400 font-bold\">\u25b6 ' + esc(tc.name) + '(' + esc(JSON.stringify(tc.args || {}).slice(0, 140)) + ')</div>'\n                + '<div class=\"text-slate-300 mt-1 max-h-32 overflow-y-auto whitespace-pre-wrap\">' + esc(JSON.stringify(tc.result || {}).slice(0, 500)) + '</div>'\n                + '</div>';\n            }\n            toolsHtml += '</div></details>';\n          }\n\n          var statusBadge = isRun\n            ? '<span class=\"px-2 py-0.5 rounded bg-amber-500/20 text-amber-300 border border-amber-500/40 text-[10px] font-mono animate-pulse\">\u26a1 Running in Background...</span>'\n            : '<span class=\"text-[10px] text-slate-400 font-mono\">' + esc(m.model || 'gemini') + (m.thinking_level ? ' \u2022 think:' + esc(m.thinking_level) : '') + '</span>';\n\n          html += '<div class=\"flex justify-start\">'\n            + '<div class=\"max-w-4xl w-full bg-[#0b1120] border ' + (isRun ? 'border-amber-500/50' : 'border-slate-800/90') + ' rounded-2xl rounded-tl-sm px-4 py-3 text-sm text-slate-100 shadow\">'\n            + '<div class=\"flex items-center justify-between gap-2 mb-2 pb-1.5 border-b border-slate-800/80\">'\n            + '<div class=\"flex items-center gap-2\"><span class=\"text-amber-400 font-bold\">\u2624 Hermes</span>' + statusBadge + '</div>'\n            + '<button type=\"button\" data-speech=\"' + esc((m.content || '').replace(/\"/g, '')) + '\" onclick=\"speakText(this)\" class=\"text-xs text-slate-400 hover:text-white\" title=\"Read Aloud\">\ud83d\udd0a</button>'\n            + '</div>'\n            + thoughtsHtml\n            + toolsHtml\n            + '<div class=\"prose prose-invert max-w-none text-sm\">' + renderMd(m.content || (isRun ? '_Executing in background on Cloudflare + /data/hermes..._' : '')) + '</div>'\n            + '</div></div>';\n        }\n      }\n      container.innerHTML = html;\n      container.scrollTop = container.scrollHeight;\n    }\n\n    async function sendMessage(e) {\n      if (e) e.preventDefault();\n      closeSlashMenu();\n      var inp = document.getElementById('chatInput');\n      var text = (inp.value || '').trim();\n      if (!text && !attachedImage) return;\n\n      // Client-side tab switch shortcuts\n      if (text === '/skills') { inp.value = ''; switchTab('skills'); return; }\n      if (text === '/memory') { inp.value = ''; switchTab('memory'); return; }\n      if (text === '/kanban') { inp.value = ''; switchTab('kanban'); return; }\n      if (text === '/cron') { inp.value = ''; switchTab('cron'); return; }\n      if (text === '/jobs') { inp.value = ''; switchTab('jobs'); return; }\n      if (text === '/new') { inp.value = ''; await createNewSession(); return; }\n\n      var model = document.getElementById('modelSelect').value || 'gemini-3.8-flash';\n      var thinking = document.getElementById('thinkingSelect').value || 'auto';\n      var toolset = document.getElementById('toolsetSelect').value || 'hermes-cli';\n      var imgPayload = attachedImage;\n\n      inp.value = '';\n      clearImageAttachment();\n\n      var btn = document.getElementById('sendBtn');\n      btn.disabled = true;\n      btn.textContent = bgMode ? 'Dispatched \u26a1' : 'Thinking...';\n\n      try {\n        var payload = {\n          session_id: activeSessionId,\n          message: text,\n          model: model,\n          thinking_level: thinking,\n          toolset: toolset,\n          preloaded_skill: preloadedSkill,\n          image: imgPayload,\n          background: bgMode\n        };\n        var data = await api('/api/chat', {\n          method: 'POST',\n          body: JSON.stringify(payload)\n        });\n        if (data.session) {\n          activeSessionId = data.session.id;\n          localStorage.setItem('hermes_active_session', activeSessionId);\n          activeGoal = data.session.goal || '';\n          updateGoalBanner();\n          renderMessages(data.session.messages || []);\n          updateRunningBanner(data.session.messages || []);\n          window._wasRunningLastPoll = (data.status === 'running');\n        }\n        loadSessionsQuiet();\n      } catch (err) {\n        alert('Error sending message: ' + (err.message || err));\n      } finally {\n        btn.disabled = false;\n        btn.textContent = 'Send \u21b5';\n      }\n    }\n\n    // ------------------------------------------------------------------------\n    // TAB 2: BACKGROUND JOBS MONITOR\n    // ------------------------------------------------------------------------\n    async function loadJobsTab() {\n      var el = document.getElementById('jobsListContainer');\n      if (!el) return;\n      try {\n        var data = await api('/api/jobs');\n        var jobs = data.jobs || [];\n        var navCount = document.getElementById('navJobCount');\n        if (navCount) navCount.textContent = String(jobs.length);\n        if (jobs.length === 0) {\n          el.innerHTML = '<div class=\"p-6 text-center text-xs text-slate-400 bg-[#0a0f1c] border border-slate-800 rounded-xl\">No background jobs recorded yet. Send any message with <b>\ud83d\udd04 Keep-Alive: ON</b> and it will execute here even if you close your phone browser!</div>';\n          return;\n        }\n        var html = '';\n        for (var i = 0; i < jobs.length; i++) {\n          var j = jobs[i];\n          var isRun = j.status === 'running';\n          var badge = isRun\n            ? '<span class=\"px-2 py-0.5 rounded bg-amber-500/20 text-amber-300 border border-amber-500/40 text-xs font-mono animate-pulse\">\u26a1 RUNNING</span>'\n            : (j.status === 'done'\n              ? '<span class=\"px-2 py-0.5 rounded bg-emerald-500/20 text-emerald-300 border border-emerald-500/40 text-xs font-mono\">\u2705 DONE</span>'\n              : '<span class=\"px-2 py-0.5 rounded bg-rose-500/20 text-rose-300 border border-rose-500/40 text-xs font-mono\">\u274c ERROR</span>');\n          html += '<div class=\"p-3.5 rounded-xl bg-[#0a0f1c] border border-slate-800 flex flex-wrap items-center justify-between gap-2\">'\n            + '<div class=\"space-y-1 max-w-3xl\">'\n            + '<div class=\"flex items-center gap-2\">' + badge + '<span class=\"text-xs font-mono text-indigo-300\">' + esc(j.model || '') + '</span><span class=\"text-[11px] text-slate-400\">' + esc(j.started_at || '') + '</span></div>'\n            + '<div class=\"text-xs text-white font-semibold\">' + esc(j.prompt_preview || '') + '</div>'\n            + (j.tool_count ? '<div class=\"text-[11px] text-emerald-400 font-mono\">\ud83d\udee0\ufe0f Executed ' + j.tool_count + ' tool calls on /data/hermes</div>' : '')\n            + '</div>'\n            + '<button type=\"button\" onclick=\"selectSession(\\'' + esc(j.session_id) + '\\'); switchTab(\\'chat\\');\" class=\"px-3 py-1.5 rounded-lg bg-slate-800 hover:bg-slate-700 text-xs text-slate-200\">Open Session \u2192</button>'\n            + '</div>';\n        }\n        el.innerHTML = html;\n      } catch (e) {}\n    }\n\n    // ------------------------------------------------------------------------\n    // TAB 3: LIVE TERMINAL & CODE SANDBOX\n    // ------------------------------------------------------------------------\n    async function execTerminalForm(e) {\n      if (e) e.preventDefault();\n      var cmd = document.getElementById('termCmdInput').value.trim();\n      var cwd = document.getElementById('termWorkdir').value.trim() || '/data/hermes';\n      if (!cmd) return;\n      document.getElementById('termCmdInput').value = '';\n      await runQuickTerm(cmd, cwd);\n    }\n\n    async function runQuickTerm(cmd, cwd) {\n      cwd = cwd || (document.getElementById('termWorkdir') ? document.getElementById('termWorkdir').value : '/data/hermes');\n      var out = document.getElementById('termOutput');\n      out.textContent += '\\n\\nroot@az-spot-vm:' + cwd + '$ ' + cmd + '\\nRunning...';\n      out.scrollTop = out.scrollHeight;\n      try {\n        var res = await api('/api/terminal', {\n          method: 'POST',\n          body: JSON.stringify({ command: cmd, workdir: cwd })\n        });\n        out.textContent += '\\n' + (res.stdout || '') + (res.stderr ? '\\n[stderr] ' + res.stderr : '') + '\\n[exit ' + (res.exit_code != null ? res.exit_code : 0) + ']';\n        out.scrollTop = out.scrollHeight;\n      } catch (err) {\n        out.textContent += '\\nError: ' + err.message;\n      }\n    }\n\n    async function runSandboxCode() {\n      var lang = document.getElementById('codeLangSelect').value;\n      var code = document.getElementById('codeEditorInput').value;\n      var out = document.getElementById('codeRunnerOutput');\n      out.textContent = 'Executing ' + lang + ' on Spot VM (/data/hermes)...';\n      try {\n        var res = await api('/api/code', {\n          method: 'POST',\n          body: JSON.stringify({ language: lang, code: code })\n        });\n        out.textContent = (res.stdout || '') + (res.stderr ? '\\n[stderr]\\n' + res.stderr : '') || '(No output, exit 0)';\n      } catch (err) {\n        out.textContent = 'Error: ' + err.message;\n      }\n    }\n\n    // ------------------------------------------------------------------------\n    // TAB 4: SKILLS HUB (60+ SKILLS)\n    // ------------------------------------------------------------------------\n    async function loadSkillsTab() {\n      try {\n        var data = await api('/api/skills');\n        skills = data.skills || [];\n        var cnt = document.getElementById('navSkillCount');\n        if (cnt) cnt.textContent = String(skills.length);\n        var catSel = document.getElementById('skillCategoryFilter');\n        if (catSel && data.categories) {\n          var cur = catSel.value;\n          var html = '<option value=\"\">All Categories (' + skills.length + ')</option>';\n          for (var i = 0; i < data.categories.length; i++) {\n            var c = data.categories[i];\n            html += '<option value=\"' + esc(c) + '\">' + esc(c) + '</option>';\n          }\n          catSel.innerHTML = html;\n          catSel.value = cur;\n        }\n        renderSkillsList();\n        if (!selectedSkillName && skills.length > 0) {\n          inspectSkill(skills[0].name);\n        }\n      } catch (e) {}\n    }\n\n    function renderSkillsList() {\n      var q = (document.getElementById('skillSearchInput').value || '').toLowerCase();\n      var cat = document.getElementById('skillCategoryFilter').value || '';\n      var el = document.getElementById('skillsListContainer');\n      if (!el) return;\n      var html = '';\n      for (var i = 0; i < skills.length; i++) {\n        var s = skills[i];\n        if (cat && s.category !== cat) continue;\n        if (q && s.name.toLowerCase().indexOf(q) === -1 && (s.description || '').toLowerCase().indexOf(q) === -1) continue;\n        html += '<div onclick=\"inspectSkill(\\'' + esc(s.name) + '\\')\" class=\"p-2.5 rounded-xl bg-slate-900/70 hover:bg-slate-800 border border-slate-800 cursor-pointer transition\">'\n          + '<div class=\"flex items-center justify-between\">'\n          + '<span class=\"text-xs font-bold text-indigo-300 font-mono\">' + esc(s.name) + '</span>'\n          + '<span class=\"text-[10px] px-1.5 py-0.5 rounded bg-slate-800 text-slate-400\">' + esc(s.category || 'general') + '</span>'\n          + '</div>'\n          + '<div class=\"text-[11px] text-slate-400 mt-1 line-clamp-2\">' + esc(s.description || '') + '</div>'\n          + '</div>';\n      }\n      el.innerHTML = html || '<div class=\"text-xs text-slate-500 p-3\">No matching skills</div>';\n    }\n\n    async function inspectSkill(name) {\n      selectedSkillName = name;\n      document.getElementById('skillViewerTitle').textContent = name;\n      document.getElementById('useSkillBtn').classList.remove('hidden');\n      document.getElementById('saveSkillBtn').classList.remove('hidden');\n      try {\n        var data = await api('/api/skills/' + encodeURIComponent(name));\n        document.getElementById('skillContentEditor').value = data.content || '';\n        document.getElementById('skillViewerMeta').textContent = data.skill ? '[' + (data.skill.category || 'custom') + ']' : '';\n      } catch (e) {}\n    }\n\n    function openNewSkillEditor() {\n      var name = prompt('Enter new skill identifier (e.g. kubernetes-spot-recovery):');\n      if (!name) return;\n      selectedSkillName = name.trim().toLowerCase().replace(/[^a-z0-9-_]/g, '-');\n      document.getElementById('skillViewerTitle').textContent = selectedSkillName;\n      document.getElementById('useSkillBtn').classList.remove('hidden');\n      document.getElementById('saveSkillBtn').classList.remove('hidden');\n      document.getElementById('skillContentEditor').value = '---\\nname: ' + selectedSkillName + '\\ncategory: custom\\ndescription: Custom procedural skill stored on /data/hermes\\n---\\n\\n# ' + selectedSkillName + '\\n\\n## Procedure\\n1. Step one\\n2. Step two\\n';\n    }\n\n    async function saveSkillFromEditor() {\n      if (!selectedSkillName) return;\n      var content = document.getElementById('skillContentEditor').value;\n      try {\n        await api('/api/skills', {\n          method: 'POST',\n          body: JSON.stringify({ name: selectedSkillName, category: 'custom', description: 'Saved via Hermes Web UI', content: content })\n        });\n        await loadSkillsTab();\n        alert('Saved skill ' + selectedSkillName + ' to /data/hermes/.hermes/skills/ and Cloudflare R2!');\n      } catch (e) {}\n    }\n\n    function activateSkillInChat() {\n      if (!selectedSkillName) return;\n      preloadedSkill = selectedSkillName;\n      document.getElementById('activeSkillName').textContent = selectedSkillName;\n      document.getElementById('activeSkillBanner').classList.remove('hidden');\n      switchTab('chat');\n    }\n\n    // ------------------------------------------------------------------------\n    // TAB 5: MEMORY & PERSONA (SOUL.md, MEMORY.md, USER.md)\n    // ------------------------------------------------------------------------\n    async function loadMemoryTab() {\n      try {\n        var data = await api('/api/memories');\n        var p = data.persona || {};\n        var mf = data.memory_files || {};\n        document.getElementById('soulMdInput').value = p.soul_md || mf['SOUL.md'] || '';\n        document.getElementById('memoryMdInput').value = p.memory_md || mf['MEMORY.md'] || '';\n        document.getElementById('userMdInput').value = p.user_md || mf['USER.md'] || '';\n        var list = data.memories || [];\n        var el = document.getElementById('memoryFactsList');\n        var html = '';\n        for (var i = 0; i < list.length; i++) {\n          var m = list[i];\n          var factTxt = m.text || m.content || '';\n          if (!factTxt) continue;\n          html += '<div class=\"p-2.5 rounded-lg bg-slate-900 border border-slate-800 flex items-start justify-between gap-2 text-xs\">'\n            + '<div class=\"text-slate-200\">' + esc(factTxt) + '</div>'\n            + '<button type=\"button\" onclick=\"deleteMemoryFact(\\'' + esc(m.id) + '\\')\" class=\"text-slate-500 hover:text-red-400\">\u2715</button>'\n            + '</div>';\n        }\n        el.innerHTML = html || '<div class=\"text-xs text-slate-500\">No structured facts yet.</div>';\n      } catch (e) {}\n    }\n\n    function applyPersonaPreset() {\n      var v = document.getElementById('personaPresetSelect').value;\n      if (!v) return;\n      var presets = {\n        default: '# Hermes Agent Persona (SOUL.md)\\nYou are Hermes Agent \u2624, an autonomous self-improving AI engineered by Nous Research.\\nYou act decisively, verify every change end-to-end on /data/hermes, and remember key facts.',\n        architect: '# Principal Cloud & Systems Architect (SOUL.md)\\nYou are a Principal Distributed Systems & Cloud Architect specializing in Spot VM resilience, Kubernetes, Cloudflare Workers, and Vertex AI.',\n        researcher: '# Deep Scientific & AI Researcher (SOUL.md)\\nYou conduct rigorous multi-source technical research, cross-check citations, and synthesize findings with mathematical clarity.',\n        coder: '# Autonomous Full-Stack Engineer (SOUL.md)\\nYou write clean, production-hardened code, test everything via terminal & execute_code on /data/hermes, and never leave placeholders.',\n        concise: '# Ultra-Concise Executive Mode (SOUL.md)\\nRespond with maximum signal-to-noise ratio: bullet points, exact commands, and verified outcomes.'\n      };\n      if (presets[v]) document.getElementById('soulMdInput').value = presets[v];\n    }\n\n    async function savePersonaFiles() {\n      try {\n        await api('/api/memories', {\n          method: 'POST',\n          body: JSON.stringify({\n            action: 'update_files',\n            soul_md: document.getElementById('soulMdInput').value,\n            memory_md: document.getElementById('memoryMdInput').value,\n            user_md: document.getElementById('userMdInput').value\n          })\n        });\n        alert('Saved SOUL.md, MEMORY.md, and USER.md to /data/hermes/.hermes/ and Cloudflare R2!');\n      } catch (e) {}\n    }\n\n    async function addMemoryFact(e) {\n      if (e) e.preventDefault();\n      var inp = document.getElementById('newMemoryFactInput');\n      var txt = inp.value.trim();\n      if (!txt) return;\n      inp.value = '';\n      await api('/api/memories', {\n        method: 'POST',\n        body: JSON.stringify({ action: 'add_fact', text: txt, category: 'general' })\n      });\n      await loadMemoryTab();\n    }\n\n    async function deleteMemoryFact(id) {\n      await api('/api/memories', {\n        method: 'POST',\n        body: JSON.stringify({ action: 'delete_fact', id: id })\n      });\n      await loadMemoryTab();\n    }\n\n    // ------------------------------------------------------------------------\n    // TAB 6: KANBAN & TODOS\n    // ------------------------------------------------------------------------\n    async function loadKanbanTab() {\n      try {\n        var data = await api('/api/kanban');\n        var cards = data.kanban || data.tasks || [];\n        var cols = ['todo', 'in_progress', 'review', 'blocked', 'done'];\n        for (var c = 0; c < cols.length; c++) {\n          var colEl = document.getElementById('kb-col-' + cols[c]);\n          if (colEl) colEl.innerHTML = '';\n        }\n        for (var i = 0; i < cards.length; i++) {\n          var k = cards[i];\n          var col = document.getElementById('kb-col-' + (k.column || 'todo')) || document.getElementById('kb-col-todo');\n          if (!col) continue;\n          var cardHtml = '<div class=\"p-2.5 rounded-lg bg-slate-900 border border-slate-800 space-y-2 text-xs\">'\n            + '<div class=\"flex items-start justify-between gap-1\">'\n            + '<span class=\"font-semibold text-white\">' + esc(k.title) + '</span>'\n            + '<button type=\"button\" onclick=\"deleteKanbanCard(\\'' + esc(k.id) + '\\')\" class=\"text-slate-500 hover:text-red-400\">\u2715</button>'\n            + '</div>'\n            + (k.result ? '<div class=\"text-[11px] text-emerald-300 bg-slate-950 p-1.5 rounded max-h-24 overflow-y-auto whitespace-pre-wrap\">' + esc(k.result.slice(0, 280)) + '</div>' : '')\n            + '<div class=\"flex flex-wrap gap-1 pt-1\">'\n            + '<button type=\"button\" onclick=\"dispatchKanbanSubagent(\\'' + esc(k.id) + '\\')\" class=\"px-2 py-0.5 bg-indigo-600/30 hover:bg-indigo-600/50 text-indigo-200 rounded text-[10px]\">\ud83e\udd16 Run Subagent</button>'\n            + '<button type=\"button\" onclick=\"moveKanbanCard(\\'' + esc(k.id) + '\\', \\'done\\')\" class=\"px-2 py-0.5 bg-emerald-600/20 text-emerald-300 rounded text-[10px]\">\u2713 Done</button>'\n            + '</div></div>';\n          col.innerHTML += cardHtml;\n        }\n        var todos = data.todos || [];\n        var todoEl = document.getElementById('todoListContainer');\n        var th = '';\n        for (var j = 0; j < todos.length; j++) {\n          var td = todos[j];\n          th += '<div class=\"p-2 rounded bg-slate-900 border border-slate-800 flex items-center justify-between gap-2 text-xs\">'\n            + '<span class=\"' + (td.status === 'done' ? 'line-through text-slate-500' : 'text-slate-200') + '\">' + esc(td.title) + '</span>'\n            + '<button type=\"button\" onclick=\"toggleTodoUI(\\'' + esc(td.id) + '\\', \\'' + (td.status === 'done' ? 'pending' : 'done') + '\\')\" class=\"text-emerald-400 text-xs\">\u2713</button>'\n            + '</div>';\n        }\n        if (todoEl) todoEl.innerHTML = th || '<div class=\"text-xs text-slate-500\">No todos yet</div>';\n      } catch (e) {}\n    }\n\n    async function createKanbanCardUI(e) {\n      if (e) e.preventDefault();\n      var title = document.getElementById('kbTitleInput').value.trim();\n      var prio = document.getElementById('kbPriorityInput').value;\n      if (!title) return;\n      document.getElementById('kbTitleInput').value = '';\n      await api('/api/kanban', {\n        method: 'POST',\n        body: JSON.stringify({ action: 'create', title: title, priority: prio, column: 'todo' })\n      });\n      await loadKanbanTab();\n    }\n\n    async function moveKanbanCard(id, col) {\n      await api('/api/kanban', {\n        method: 'POST',\n        body: JSON.stringify({ action: 'move', id: id, column: col })\n      });\n      await loadKanbanTab();\n    }\n\n    async function dispatchKanbanSubagent(id) {\n      await api('/api/kanban', {\n        method: 'POST',\n        body: JSON.stringify({ action: 'dispatch', id: id, model: document.getElementById('modelSelect').value, background: true })\n      });\n      await loadKanbanTab();\n      setTimeout(loadKanbanTab, 3500);\n    }\n\n    async function deleteKanbanCard(id) {\n      await api('/api/kanban', {\n        method: 'POST',\n        body: JSON.stringify({ action: 'delete', id: id })\n      });\n      await loadKanbanTab();\n    }\n\n    async function addTodoUI(e) {\n      if (e) e.preventDefault();\n      var inp = document.getElementById('todoTitleInput');\n      var t = inp.value.trim();\n      if (!t) return;\n      inp.value = '';\n      await api('/api/todos', {\n        method: 'POST',\n        body: JSON.stringify({ action: 'add', title: t })\n      });\n      await loadKanbanTab();\n    }\n\n    async function toggleTodoUI(id, status) {\n      await api('/api/todos', {\n        method: 'POST',\n        body: JSON.stringify({ action: 'update', id: id, status: status })\n      });\n      await loadKanbanTab();\n    }\n\n    // ------------------------------------------------------------------------\n    // TAB 7: CRON AUTOMATIONS\n    // ------------------------------------------------------------------------\n    async function loadCronTab() {\n      try {\n        var data = await api('/api/cron');\n        var list = data.cron_jobs || [];\n        var el = document.getElementById('cronJobsContainer');\n        var html = '';\n        for (var i = 0; i < list.length; i++) {\n          var c = list[i];\n          html += '<div class=\"p-4 rounded-xl bg-[#0a0f1c] border border-slate-800 space-y-2\">'\n            + '<div class=\"flex flex-wrap items-center justify-between gap-2\">'\n            + '<div><span class=\"text-sm font-bold text-white\">' + esc(c.name) + '</span> <span class=\"text-xs font-mono text-amber-300 ml-2\">' + esc(c.schedule) + '</span></div>'\n            + '<div class=\"flex gap-1.5\">'\n            + '<button type=\"button\" onclick=\"runCronNow(\\'' + esc(c.id) + '\\')\" class=\"px-2.5 py-1 bg-emerald-600 hover:bg-emerald-500 text-white text-xs rounded\">\u25b6 Run Now</button>'\n            + '<button type=\"button\" onclick=\"deleteCronJob(\\'' + esc(c.id) + '\\')\" class=\"px-2.5 py-1 bg-rose-900/60 text-rose-200 text-xs rounded\">Delete</button>'\n            + '</div></div>'\n            + '<div class=\"text-xs text-slate-300\">' + esc(c.prompt) + '</div>'\n            + (c.last_output ? '<pre class=\"bg-slate-950 p-2 rounded text-[11px] font-mono text-emerald-300 max-h-32 overflow-y-auto whitespace-pre-wrap\">' + esc(c.last_output) + '</pre>' : '')\n            + '</div>';\n        }\n        el.innerHTML = html || '<div class=\"text-xs text-slate-400\">No scheduled cron automations yet. Use the form or one-click blueprints on the left!</div>';\n      } catch (e) {}\n    }\n\n    function fillCronBlueprint(name, sched, promptText) {\n      document.getElementById('cronNameInput').value = name;\n      document.getElementById('cronSchedInput').value = sched;\n      document.getElementById('cronPromptInput').value = promptText;\n    }\n\n    async function createCronUI(e) {\n      if (e) e.preventDefault();\n      var name = document.getElementById('cronNameInput').value.trim();\n      var sched = document.getElementById('cronSchedInput').value.trim();\n      var promptText = document.getElementById('cronPromptInput').value.trim();\n      if (!name || !promptText) return;\n      await api('/api/cron', {\n        method: 'POST',\n        body: JSON.stringify({ action: 'create', name: name, schedule: sched, prompt: promptText, model: document.getElementById('modelSelect').value })\n      });\n      document.getElementById('cronNameInput').value = '';\n      document.getElementById('cronPromptInput').value = '';\n      await loadCronTab();\n    }\n\n    async function runCronNow(id) {\n      await api('/api/cron', {\n        method: 'POST',\n        body: JSON.stringify({ action: 'run_now', id: id })\n      });\n      await loadCronTab();\n    }\n\n    async function deleteCronJob(id) {\n      await api('/api/cron', {\n        method: 'POST',\n        body: JSON.stringify({ action: 'delete', id: id })\n      });\n      await loadCronTab();\n    }\n\n    // ------------------------------------------------------------------------\n    // TAB 8: /data FILE EXPLORER\n    // ------------------------------------------------------------------------\n    async function browseFiles() {\n      var p = document.getElementById('filePathInput').value.trim() || '/data/hermes';\n      try {\n        var data = await api('/api/files?path=' + encodeURIComponent(p));\n        var entries = data.entries || [];\n        var el = document.getElementById('fileTreeList');\n        var html = '';\n        for (var i = 0; i < entries.length; i++) {\n          var item = entries[i];\n          if (item.is_dir) {\n            html += '<div onclick=\"document.getElementById(\\'filePathInput\\').value=\\'' + esc(item.path) + '\\'; browseFiles();\" class=\"p-1.5 rounded hover:bg-slate-800 cursor-pointer text-amber-300 flex items-center justify-between\">'\n              + '<span>\ud83d\udcc1 ' + esc(item.name) + '/</span></div>';\n          } else {\n            html += '<div onclick=\"openFileInEditor(\\'' + esc(item.path) + '\\')\" class=\"p-1.5 rounded hover:bg-slate-800 cursor-pointer text-slate-200 flex items-center justify-between\">'\n              + '<span>\ud83d\udcc4 ' + esc(item.name) + '</span><span class=\"text-[10px] text-slate-500\">' + (item.size || 0) + 'B</span></div>';\n          }\n        }\n        el.innerHTML = html || '<div class=\"text-xs text-slate-500 p-2\">Empty directory</div>';\n      } catch (e) {}\n    }\n\n    function browseParentDir() {\n      var p = document.getElementById('filePathInput').value.trim() || '/data/hermes';\n      var parts = p.split('/').filter(Boolean);\n      if (parts.length > 1) parts.pop();\n      document.getElementById('filePathInput').value = '/' + parts.join('/');\n      browseFiles();\n    }\n\n    async function openFileInEditor(path) {\n      document.getElementById('openFilePath').textContent = path;\n      var data = await api('/api/files?path=' + encodeURIComponent(path) + '&mode=read');\n      document.getElementById('fileEditorContent').value = data.content || '';\n    }\n\n    async function saveOpenFile() {\n      var path = document.getElementById('openFilePath').textContent;\n      var content = document.getElementById('fileEditorContent').value;\n      await api('/api/files', {\n        method: 'POST',\n        body: JSON.stringify({ action: 'write', path: path, content: content })\n      });\n      alert('Saved ' + path + ' to /data!');\n      browseFiles();\n    }\n\n    async function grepFilesUI() {\n      var q = document.getElementById('fileSearchQuery').value.trim();\n      var p = document.getElementById('filePathInput').value.trim() || '/data/hermes';\n      if (!q) return;\n      var data = await api('/api/files', {\n        method: 'POST',\n        body: JSON.stringify({ action: 'search', path: p, pattern: q })\n      });\n      document.getElementById('openFilePath').textContent = 'grep results for: ' + q;\n      document.getElementById('fileEditorContent').value = data.matches || 'No matches found.';\n    }\n\n    // ------------------------------------------------------------------------\n    // TAB 9: SYSTEM, DOCTOR & ANALYTICS\n    // ------------------------------------------------------------------------\n    async function loadSystemOverview() {\n      try {\n        var data = await api('/api/system');\n        var cards = document.getElementById('systemStatsCards');\n        if (cards) {\n          var a = data.analytics || {};\n          cards.innerHTML = '<div class=\"p-3.5 rounded-xl bg-[#0a0f1c] border border-slate-800\"><div class=\"text-xs text-slate-400\">Vertex AI Models</div><div class=\"text-xl font-bold text-indigo-400\">21 Live</div></div>'\n            + '<div class=\"p-3.5 rounded-xl bg-[#0a0f1c] border border-slate-800\"><div class=\"text-xs text-slate-400\">Hermes Tools & Skills</div><div class=\"text-xl font-bold text-emerald-400\">19 Tools / ' + (a.total_skills || 60) + ' Skills</div></div>'\n            + '<div class=\"p-3.5 rounded-xl bg-[#0a0f1c] border border-slate-800\"><div class=\"text-xs text-slate-400\">Sessions & Messages</div><div class=\"text-xl font-bold text-sky-400\">' + (a.total_sessions || 0) + ' / ' + (a.total_messages || 0) + '</div></div>'\n            + '<div class=\"p-3.5 rounded-xl bg-[#0a0f1c] border border-slate-800\"><div class=\"text-xs text-slate-400\">Spot VM /data Persistence</div><div class=\"text-xl font-bold text-amber-400\">Active (SQLite + R2)</div></div>';\n        }\n        var proc = document.getElementById('processesOutput');\n        if (proc && data.vm) {\n          proc.textContent = '=== Spot VM Systemd Services ===\\n' + JSON.stringify(data.vm.services || {}, null, 2)\n            + '\\n\\n=== /data Disk Usage ===\\n' + (data.vm.disk_df || '')\n            + '\\n\\n=== Memory ===\\n' + (data.vm.mem_free || '');\n        }\n        var docOut = document.getElementById('doctorOutput');\n        if (docOut && docOut.textContent.indexOf('Click ') === 0) {\n          docOut.textContent = '\u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\\n'\n            + '\u2502                 \u2624 Hermes Agent Status                  \u2502\\n'\n            + '\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\\n\\n'\n            + '  Host:         ' + ((data.vm && data.vm.hostname) || 'az-spot-vm') + ' (/data/hermes)\\n'\n            + '  Provider:     Google Vertex AI (your-gcp-project-id) \u2014 21 Models Online\\n'\n            + '  Bridge URL:   ' + ((data.vm && data.vm.tunnel_url) || 'Connected') + '\\n'\n            + '  Skills Hub:   ' + ((data.analytics && data.analytics.total_skills) || 60) + ' procedural skills on /data/hermes/.hermes/skills\\n'\n            + '  Toolsets:     19 native Hermes tools active (bash, code, files, web, moa, memory, kanban, cron)\\n'\n            + '  Persistence:  /data/hermes/storage/hermes_store.db + Cloudflare R2 Mirror\\n'\n            + '  Keep-Alive:   Unstoppable Background Execution (ctx.waitUntil + Spot VM Bridge)\\n\\n'\n            + '\u2713 All Spot VM & Cloudflare Edge subsystems verified healthy.';\n        }\n      } catch (e) {}\n    }\n\n    async function runHermesDoctor(subcmd) {\n      var out = document.getElementById('doctorOutput');\n      out.textContent = 'Running hermes ' + subcmd + ' on Spot VM (/data/hermes)...';\n      try {\n        var res = await api('/api/terminal', {\n          method: 'POST',\n          body: JSON.stringify({ command: 'hermes ' + subcmd, workdir: '/data/hermes' })\n        });\n        out.textContent = (res.stdout || '') + (res.stderr ? '\\n' + res.stderr : '');\n      } catch (err) {\n        out.textContent = 'Error: ' + err.message;\n      }\n    }\n\n    // ------------------------------------------------------------------------\n    // BOOTSTRAP\n    // ------------------------------------------------------------------------\n    async function bootWorkspace() {\n      updateBgModeButton();\n      populateModelDropdown(FALLBACK_MODELS);\n      var savedThinking = localStorage.getItem('hermes_thinking_level');\n      if (savedThinking && document.getElementById('thinkingSelect')) {\n        document.getElementById('thinkingSelect').value = savedThinking;\n      }\n      var savedToolset = localStorage.getItem('hermes_toolset');\n      if (savedToolset && document.getElementById('toolsetSelect')) {\n        document.getElementById('toolsetSelect').value = savedToolset;\n      }\n      if (!authToken) {\n        document.getElementById('loginOverlay').classList.remove('hidden');\n        return;\n      }\n      try {\n        await loadModels();\n        await loadSessions();\n        loadSessionsQuiet();\n        startBackgroundPoller();\n      } catch (e) {}\n    }\n\n    window.addEventListener('DOMContentLoaded', bootWorkspace);\n  </script>\n</body>\n</html>";
}
